(window.RAGHIB = window.RAGHIB || {})["2-7"] = [
  {"a": [181, 181], "h": "\"Whoever changes it after hearing it\" — and the worst change of all: a false report in the Prophet's name", "hAr": "﴿فَمَنۢ بَدَّلَهُۥ بَعۡدَ مَا سَمِعَهُۥ﴾ — وأعظم التبديل: خبرٌ مكذوبٌ على صاحب الشرع", "said": "والهاء في \" إثمه \" للتبديل ومن: عام في الوصي والموصى له، والشاهد والحاكم وكل من له مدخل في ذلك إذا غير شيئا بعدما سمعه أي علمه، فإن إثم ما يجري في ذلك راجع إليه تنبيها على ما قاله - عليه السلام: (من سن سنة سيئة فعليه وزرها ووزر من عمل بها) وأعظم ذلك ما لا يعرف المستن ... كمن ادعى على صاحب الشرع خبرا يتعلق به حكم، فيعتمد عليه الناس بعده ... ونبه بقوله: ﴿إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ﴾ أن ذلك وإن خفي على الناس، فلن يخفى عليه تعالى", "en": "\"Whoever changes it\" covers everyone with a hand in a will — the executor, the beneficiary, the witness, the judge: whoever alters anything after he has heard, that is, known it, carries the sin of all that follows from it. As the Prophet ﷺ said, \"whoever starts a bad practice bears its burden and the burden of all who act on it\".\nAnd the gravest case of all is where those who follow cannot know that it was a fabrication — like one who falsely attributes to the Prophet ﷺ a report that carries a ruling, and people go on relying on it after him.\n\"On those who change it\" — the sin is for the changing, not for anything else. \"Allah is Hearing, Knowing\": though it be hidden from people, it is not hidden from Him — He knows the treachery of the eyes and what the hearts conceal.", "ar": "الهاء في ﴿إِثۡمُهُۥ﴾ للتبديل، و«مَن» عامٌّ في الوصيّ والموصى له والشاهد والحاكم وكلّ من له مدخلٌ في ذلك: إذا غيّر شيئًا بعدما سمعه — أي علمه — فإثم ما يجري من ذلك راجعٌ إليه، كما قال ﷺ: «من سنّ سنّةً سيّئة فعليه وزرها ووزر من عمل بها».\nوأعظم ذلك ما لا يعرف المتّبع فيه أنه مختلَق: كمن ادّعى على صاحب الشرع خبرًا يتعلّق به حكم، فيعتمد عليه الناس بعده.\nوقال ﴿عَلَى ٱلَّذِينَ يُبَدِّلُونَهُۥٓۚ﴾ ليبيّن أن الإثم للتبديل لا لغيره؛ ونبّه بـ﴿إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ﴾ أن ذلك وإن خفي على الناس لم يخفَ عليه، فهو يعلم خائنة الأعين وما تخفي الصدور.", "links": [{"ref": "16:25", "q": "﴿لِيَحۡمِلُوٓاْ أَوۡزَارَهُمۡ كَامِلَةٗ يَوۡمَ ٱلۡقِيَٰمَةِ وَمِنۡ أَوۡزَارِ ٱلَّذِينَ يُضِلُّونَهُم بِغَيۡرِ عِلۡمٍۗ﴾", "en": "Carrying the burden of those misled", "ar": "حمل أوزار من أضلّوهم"}, {"ref": "40:19", "q": "﴿يَعۡلَمُ خَآئِنَةَ ٱلۡأَعۡيُنِ وَمَا تُخۡفِي ٱلصُّدُورُ﴾", "en": "Nothing hidden from Him", "ar": "لا يخفى عليه شيء"}, {"ref": "16:116", "q": "﴿وَلَا تَقُولُواْ لِمَا تَصِفُ أَلۡسِنَتُكُمُ ٱلۡكَذِبَ هَٰذَا حَلَٰلٞ وَهَٰذَا حَرَامٞ لِّتَفۡتَرُواْ عَلَى ٱللَّهِ ٱلۡكَذِبَۚ﴾", "en": "Forging rulings in Allah's name", "ar": "الافتراء في الأحكام"}], "v": 1, "p": 383, "pe": 384, "sid": 384},
  {"a": [182, 182], "h": "\"Whoever fears a testator's injustice and puts it right — no sin on him\"", "hAr": "﴿فَمَنۡ خَافَ مِن مُّوصٖ جَنَفًا أَوۡ إِثۡمٗا فَأَصۡلَحَ بَيۡنَهُمۡ فَلَآ إِثۡمَ عَلَيۡهِۚ﴾", "said": "وقوله: ﴿بَيۡنَهُمۡ﴾ أي بين القوم الذين لهم مدخل في ذلك من الورثة والموصى لهم، وجاز إضمارهم لدلالة الكلام على ذكرهم. إن قيل: كيف قال: ﴿جَنَفًا أَوۡ إِثۡمٗا﴾ والجنف هو الإثم؟ قيل: قد قال الربيع: الجنف في الخطأ، والإثم في العمد ... ولا فرق بين أن يخاف منه ذلك، قبل موت الموصي فيرشده، أو بعد موته فيصلحه، وليس الإصلاح بمقصور على إيقاع الصلح دون استعمال الصلاح، بل يتناولهما، وإنما قال: ﴿فَلَآ إِثۡمَ عَلَيۡهِۚ﴾ لأنه لما خوف في الآية الأولى من تغيير الوصية بين أن النهي عن تغييره فيما لا جنف فيه ولا إثم [على صاحبه]، فأما إذا كان فيه شيء من ذلك فلا إثم [في تغييره]", "en": "Janaf is leaning toward injustice in a will — for example, as Tawus described, making a bequest to a grandson so that the money reaches his father, an heir; or to a son-in-law so that it reaches the daughter; or singling out where the law wants all included, or including all where it wants some singled out. \"Between them\" — among those concerned, the heirs and the beneficiaries.\n\"Injustice or sin\" — are they not the same? Ar-Rabi': janaf is by mistake, ithm on purpose; or ithm is the graver wrong. It makes no difference whether one sees it coming before the testator dies, and guides him, or after, and corrects it; and \"putting right\" means both making peace between the parties and setting the will right.\nWhy \"no sin on him\", after the warning against changing a will? Because that warning covers a will with no injustice or sin in it; where there is, changing it is no sin. \"Allah is Forgiving, Merciful\" — He overlooks whatever the one putting it right may miss, when he did his best.", "ar": "«الجنف» الميل إلى الجور في الوصيّة: كما قال طاوس: أن يوصي الرجل لابن ابنه ليصل المال إلى أبيه — وهو وارث —، أو لزوج ابنته ليوصله إليها؛ أو يخصّ حيث يجب العموم، أو يعمّ حيث يجب الخصوص. و﴿بَيۡنَهُمۡ﴾: بين من لهم مدخلٌ في ذلك من الورثة والموصى لهم.\nو﴿جَنَفًا أَوۡ إِثۡمٗا﴾ والجنف إثم؟ قال الربيع: الجنف في الخطأ، والإثم في العمد؛ وقيل: الإثم ما كبرت معصيته، والجنف ما دون ذلك. ولا فرق بين أن يخاف ذلك قبل موت الموصي فيرشده، أو بعده فيصلحه؛ والإصلاح يتناول إيقاع الصلح واستعمال الصلاح معًا.\nوإنما قال ﴿فَلَآ إِثۡمَ عَلَيۡهِۚ﴾ لأنه لمّا خوّف في الآية السابقة من تغيير الوصيّة، بيّن أن النهي عن تغييرها فيما لا جنف فيه ولا إثم، فأمّا إن كان فيها شيءٌ من ذلك فلا إثم في تغييرها. و﴿إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ﴾: يتجاوز عمّا عسى أن يفوت المصلح ممّا لم يجده.", "links": [{"ref": "4:128", "q": "﴿فَلَا جُنَاحَ عَلَيۡهِمَآ أَن يُصۡلِحَا بَيۡنَهُمَا صُلۡحٗاۚ وَٱلصُّلۡحُ خَيۡرٞۗ﴾", "en": "Putting things right is good", "ar": "الصلح خير"}, {"ref": "8:1", "q": "﴿فَٱتَّقُواْ ٱللَّهَ وَأَصۡلِحُواْ ذَاتَ بَيۡنِكُمۡۖ﴾", "en": "Setting relations right", "ar": "إصلاح ذات البين"}], "v": 1, "p": 384, "pe": 385, "sid": 385},
  {"a": [183, 183], "h": "What fasting does — it trains the soul, and lifts a person toward the angels", "hAr": "ما يفعله الصوم — يروّض النفس ويرفع الإنسان نحو الملائكة", "said": "الصوم في اللغة إمساك عما تنازع إليه النفس ... وللصوم فائدتان: إحداهما: قريبة، وهي أن يروض الإنسان به نفسه عما تدعوه إليه من الشهوات القبيحة، فإنه يعودها الصبر ... والفائدة الثانية: وهي أن فيه الاقتداء بالملأ الأعلى على قدر الوسع والتنزه عن مشاكلة البهائم التي غايتها شبع البطن والفرج، ووجه ذلك أن الإنسان مركب من بدن يسوسه سوس الحيوان وغذاؤه المطاعم، ومن روح ذي عقل غذاؤه العلم والفضائل، ومتى أكثر غذاء أحدهما قوي على ما نقص غذاؤه", "en": "In the language, fasting is holding back from what the soul pulls toward — food, drink, marriage, even speech (\"I have vowed a fast to the Most Merciful\"). In the law, it is holding back, with intention, from dawn to nightfall.\nFasting has two benefits. The near one: a person trains his soul away from the ugly appetites it calls him to, and accustoms it to patience. The soul \"commands evil\"; but placed under the law's care, it learns to let go — as the poet said, the soul wants more when you feed its wants, and is content when brought back to little. (Some read \"seek help through patience\" as \"through fasting\".)\nThe second: imitating, as far as one can, the highest company — the angels — and rising above the animals, whose whole aim is a full belly and a satisfied appetite. A human being is made of a body, governed like an animal's, whose food is meals; and a spirit with reason, whose food is knowledge and virtue. Whichever of the two is fed more grows stronger over the one that is fed less.", "ar": "«الصوم» في اللغة إمساكٌ عمّا تنازع إليه النفس — في الطعام والشراب والنكاح، بل في الكلام: ﴿إِنِّي نَذَرۡتُ لِلرَّحۡمَٰنِ صَوۡمٗا﴾ —، وفي الشرع إمساك المكلّف بنيّةٍ من الخيط الأبيض إلى الخيط الأسود.\nوللصوم فائدتان: قريبةٌ — أن يروّض الإنسان به نفسه عمّا تدعوه إليه من الشهوات القبيحة، فيعوّدها الصبر؛ فالنفس ﴿لَأَمَّارَةُۢ بِٱلسُّوٓءِ﴾، فإذا جُعلت في حِجر الشرع اعتادت الانقلاع: «والنفس راغبةٌ إذا رغّبتها — وإذا تُردّ إلى قليلٍ تقنع». (ومن هنا قيل في ﴿وَٱسۡتَعِينُواْ بِٱلصَّبۡرِ﴾: أي بالصوم.)\nوالثانية — الاقتداء بالملأ الأعلى على قدر الوسع، والتنزّه عن مشاكلة البهائم التي غايتها شبع البطن والفرج: فالإنسان مركّبٌ من بدنٍ يُساس سياسة الحيوان وغذاؤه المطاعم، ومن روحٍ ذي عقلٍ غذاؤه العلم والفضائل؛ ومتى أكثر غذاء أحدهما قوي على ما نقص غذاؤه.", "links": [{"ref": "12:53", "q": "﴿إِنَّ ٱلنَّفۡسَ لَأَمَّارَةُۢ بِٱلسُّوٓءِ﴾", "en": "The soul that must be trained", "ar": "النفس التي تحتاج إلى ترويض"}, {"ref": "2:45", "q": "﴿وَٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ﴾", "en": "\"Patience\" read as fasting", "ar": "«الصبر» بمعنى الصوم"}, {"ref": "19:26", "q": "﴿إِنِّي نَذَرۡتُ لِلرَّحۡمَٰنِ صَوۡمٗا فَلَنۡ أُكَلِّمَ ٱلۡيَوۡمَ إِنسِيّٗا﴾", "en": "Fasting from speech", "ar": "الصوم عن الكلام"}], "v": 1, "p": 385, "pe": 386, "sid": 386},
  {"a": [183, 183], "h": "Why fasting is not made permanent — and why it was prescribed for every nation", "hAr": "لماذا لم يُجعل الصوم دائمًا — ولماذا كُتب على كلّ أمّة", "said": "قيل: إن الله- عز وجل- ما خلق في الأرض وشهاه إلينا ليحرمناه، ولكن لينتفع به بقدر ما يحسن، وفي وقت ما يحسن، وألزمنا في بعض الأوقات التحرج عنه ليكون مدعاة إلى التعفف عن تناول ما لا يجوز تناوله، وجعل الله تعالى فرضه على الأهلة ليتأدب الإنسان به في كل وقت من أوقات السنة صيفا وشتاء وربيعين ... وقد تقدم أن أصول هذه العبادات لم تزل واجبة على العباد وأن النسخ على ألسنة الأنبياء في فروعها وكيفياتها وقدرها [وأزمانها]، ونبه بقوله تعالى: ﴿لَعَلَّكُمۡ تَتَّقُونَ﴾ على العلة التي لأجلها أوجب، وهي قمع الشهوة ... فإنه ذكر أنه سبب للتقوى، وتقوى الله عز وجل- واجبة على كل مكلف على كل حال وفي كل زمان", "en": "If fasting brings such virtue, why not make it permanent? Because Allah did not create what is on earth, and make it desirable to us, in order to deny it to us; He made it for us to enjoy as far as is good, and when it is good. He asked us to abstain only at certain times, as training in restraint from what is not permitted. And He tied the fast to the moon, so that over the years it moves through every season — summer, winter, spring — and trains a person in each.\n\"As it was prescribed for those before you\": the likeness has been read as the manner of fasting, or its being a few days; ar-Raghib holds that the roots of these acts of worship were always obligatory on Allah's servants, and what changed through the prophets were their details, form, amount and times.\n\"That you may become God-conscious\" gives the reason: curbing desire. That is why no nation could ever be without fasting: it is a means to God-consciousness, and God-consciousness is required of every responsible person, in every state and every age — \"We enjoined those given the Book before you, and you: be mindful of Allah\".", "ar": "فإن قيل: إذا كان الصوم سببًا لهذه الفضيلة العظيمة فهلّا أُديم فرضه؟ قيل: إن الله لم يخلق ما في الأرض ويشهّه إلينا ليحرمناه، بل لننتفع به بقدر ما يحسن وفي وقت ما يحسن، وألزمنا في بعض الأوقات التحرّج عنه ليكون مدعاةً إلى التعفّف عمّا لا يجوز تناوله؛ وجعل فرضه على الأهلّة ليتأدّب الإنسان به في كلّ وقتٍ من أوقات السنة: صيفًا وشتاءً وربيعًا.\nو﴿كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبۡلِكُمۡ﴾: قيل في الكيفيّة، وقيل في كونه أيّامًا معدودات؛ والذي قرّره الراغب أن أصول هذه العبادات لم تزل واجبةً على العباد، وأن النسخ على ألسنة الأنبياء في فروعها وكيفيّاتها وقدرها وأزمانها.\nو﴿لَعَلَّكُمۡ تَتَّقُونَ﴾: العلّة التي لأجلها أوجب — قمع الشهوة؛ ولذلك لا يجوز أن يُرفع الصوم عن أمّةٍ من الأمم، فهو سببٌ للتقوى، والتقوى واجبةٌ على كلّ مكلّفٍ في كلّ حالٍ وكلّ زمان: ﴿وَلَقَدۡ وَصَّيۡنَا ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَإِيَّاكُمۡ أَنِ ٱتَّقُواْ ٱللَّهَۚ﴾.", "links": [{"ref": "7:32", "q": "﴿قُلۡ مَنۡ حَرَّمَ زِينَةَ ٱللَّهِ ٱلَّتِيٓ أَخۡرَجَ لِعِبَادِهِۦ وَٱلطَّيِّبَٰتِ مِنَ ٱلرِّزۡقِۚ﴾", "en": "Good things made for enjoyment, not denial", "ar": "الطيّبات للانتفاع لا للحرمان"}, {"ref": "2:189", "q": "﴿يَسۡـَٔلُونَكَ عَنِ ٱلۡأَهِلَّةِۖ قُلۡ هِيَ مَوَٰقِيتُ لِلنَّاسِ وَٱلۡحَجِّۗ﴾", "en": "Worship tied to the moon", "ar": "عباداتٌ مرتبطةٌ بالأهلّة"}, {"ref": "4:131", "q": "﴿وَلَقَدۡ وَصَّيۡنَا ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَإِيَّاكُمۡ أَنِ ٱتَّقُواْ ٱللَّهَۚ﴾", "en": "One command to every nation", "ar": "وصيّةٌ واحدةٌ لكلّ الأمم"}], "v": 1, "p": 387, "pe": 388, "sid": 388},
  {"a": [184, 184], "h": "\"Those who can bear it only with great hardship\" — the words for ability, and who may give a ransom", "hAr": "﴿وَعَلَى ٱلَّذِينَ يُطِيقُونَهُۥ فِدۡيَةٞ﴾ — ألفاظ القدرة، ومن له أن يفتدي", "said": "والقدرة والاستطاعة والجهد والطاقة تتقارب، وبينها فروق، فالقدرة ما يظهر من القوة بقدر العمل لا زائدا عليه ولا ناقصا، والاستطاعة منهما ما يصير به الفعل طائعا له بسهولة، والوسع منها ما يسع له فعله بلا مشقة، والجهد ما يتعاطى به الفعل بمشقة، والطاقة منها بلوغ غاية المشقة ... وروي عن ابن عباس- رضي الله عنهما- في أصح الروايتين أن ذلك في الشيخ والشيخة الهمين والحامل والمرضع إذا خافتا على ولديهما، فلفظ (الطاقة) ههنا ينبئ عن ذلك، فإن الطاقة هي التي تبلغ غاية المشقة", "en": "Arabic has a ladder of words for ability, and ar-Raghib sets them apart: qudrah is power just equal to the task; istita'ah makes the task yield easily; wus' is what one can do without strain; juhd is doing it with strain; and taqah is reaching the utmost limit of strain.\nSo \"those who yutiqunahu\" are those for whom fasting reaches the very limit of what they can bear. In the sounder of two reports from Ibn 'Abbas, they are the very old man and woman, and the pregnant or nursing woman who fears for her child: such people may break the fast and give, for each day, the ransom of feeding a needy person. (Another report from him says that at first everyone could choose between fasting and a ransom, and the next verse ended that choice.)", "ar": "القدرة والاستطاعة والوُسع والجهد والطاقة ألفاظٌ متقاربة وبينها فروق: فـ«القدرة» ما يظهر من القوّة بقدر العمل لا زائدًا ولا ناقصًا، و«الاستطاعة» ما يصير به الفعل طائعًا بسهولة، و«الوسع» ما يسع فعله بلا مشقّة، و«الجهد» ما يُتعاطى به الفعل بمشقّة، و«الطاقة» بلوغ غاية المشقّة.\nفـ﴿ٱلَّذِينَ يُطِيقُونَهُۥ﴾ من يبلغ بهم الصوم غاية المشقّة. ورُوي عن ابن عباس — في أصحّ الروايتين — أنها في الشيخ والشيخة الكبيرين، والحامل والمرضع إذا خافتا على ولديهما: فلفظ «الطاقة» ينبئ عن ذلك، إذ هي بلوغ غاية المشقّة؛ فيجوز لهؤلاء الإفطار والفدية — طعام مسكينٍ عن كلّ يوم. (وفي روايةٍ أخرى عنه: كان الناس في الابتداء مخيّرين بين الصوم والفدية، ثم نُسخ بالآية التي بعدها.)", "links": [{"ref": "2:286", "q": "﴿لَا يُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا وُسۡعَهَاۚ﴾", "en": "Wus': what can be done without strain", "ar": "الوسع: ما يُفعل بلا مشقّة"}, {"ref": "22:78", "q": "﴿وَمَا جَعَلَ عَلَيۡكُمۡ فِي ٱلدِّينِ مِنۡ حَرَجٖۚ﴾", "en": "No hardship in the religion", "ar": "لا حرج في الدين"}], "v": 1, "p": 388, "pe": 389, "sid": 389},
  {"a": [184, 184], "h": "\"Fasting is better for you\" — the worship no one else can see", "hAr": "﴿وَأَن تَصُومُواْ خَيۡرٞ لَّكُمۡ﴾ — العبادة التي لا يطّلع عليها أحد", "said": "ويجوز أن لا يكون خيرا فعل، وإنما المعنى: الخير في الصوم تنبيها على عظيم ثوابه، وذاك أن المراد من العبادة الإخلاص والنية ... ولما كانت الأفعال البدنية كثيرا ما يدخلها الرياء إلا الصوم فإنه لا يوقف عليه ما لم يخبر الإنسان عنه بلسانه، ولا عبادة يدخل فيها الإنسان بالنية المجردة إلا الصوم ... قال عليه السلام: \" يقول الله- عز وجل الصوم لي وأنا أجزي به \"", "en": "\"And to fast is better for you\" — not only better than the ransom: the good lies in fasting itself, pointing to its great reward. What Allah wants from worship is sincerity and intention. Deeds of the body are often touched by showing off — except fasting: no one can know of it unless the person tells them. And there is no act of worship one enters by intention alone, except fasting. So the Prophet ﷺ reported that Allah says: \"Fasting is Mine, and I Myself reward it.\" \"If only you knew\" — if you understood what it brings you, you would never take it lightly.", "ar": "﴿وَأَن تَصُومُواْ خَيۡرٞ لَّكُمۡ﴾: يجوز ألّا يكون «خير» هنا للتفضيل، بل المعنى: الخير في الصوم — تنبيهًا على عظيم ثوابه. فالمراد من العبادة الإخلاص والنيّة؛ والأفعال البدنيّة كثيرًا ما يدخلها الرياء إلا الصوم، فلا يُوقف عليه ما لم يخبر الإنسان عنه بلسانه، ولا عبادة يدخل فيها الإنسان بالنيّة المجرّدة إلا الصوم؛ ولذلك قال ﷺ: «يقول الله عزّ وجل: الصوم لي وأنا أجزي به». و﴿إِن كُنتُمۡ تَعۡلَمُونَ﴾: إن عرفتم ما فيه من المنفعة لم تتهاونوا في تحمّله.", "links": [{"ref": "39:10", "q": "﴿إِنَّمَا يُوَفَّى ٱلصَّٰبِرُونَ أَجۡرَهُم بِغَيۡرِ حِسَابٖ﴾", "en": "A reward without measure", "ar": "أجرٌ بغير حساب"}, {"ref": "98:5", "q": "﴿وَمَآ أُمِرُوٓاْ إِلَّا لِيَعۡبُدُواْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ﴾", "en": "Sincerity — what worship is for", "ar": "الإخلاص مقصود العبادة"}], "v": 1, "p": 390, "pe": 390, "sid": 391},
  {"a": [185, 185], "h": "\"The month in which the Quran was sent down\" — why it is called \"Quran\", and how it came down", "hAr": "﴿شَهۡرُ رَمَضَانَ ٱلَّذِيٓ أُنزِلَ فِيهِ ٱلۡقُرۡءَانُ﴾ — لماذا سُمّي «قرآنًا» وكيف نزل", "said": "إن قيل: فلم سمي بذلك؟ قيل: إما بالنظر الجلي، فلأنه جامع للسور والآيات، وإما على نظر أدق من ذلك، فلأنه جمع فيه كل شيء محتاج إليه الناس من أمر معاشهم ومعادهم مما يتبلغون به إلى الآخرة، ولهذا قال تعالى: ﴿مَّا فَرَّطۡنَا فِي ٱلۡكِتَٰبِ مِن شَيۡءٖۚ﴾، وقال: ﴿وَتَفۡصِيلَ كُلِّ شَيۡءٖ﴾ ... وقال عطية بن الأسود لابن عباس: \" في نفسي شيء، وهو أنه قال: (شهر رمضان) وقال: ﴿إِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةِ ٱلۡقَدۡرِ﴾، وقال: ﴿إِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةٖ مُّبَٰرَكَةٍۚ﴾، وقد أنزل الله- عز وجل- القرآن في جميع الشهور، فقال: الليلة المباركة ليلة القدر، وليلة القدر في شهر رمضان، وقد أنزل الله القرآن جملة إلى البيت المعمور، ثم أنزل على محمد - صلى الله عليه وسلم - ... رسلا، وعلى هذا قوله: ﴿وَقُرۡءَانٗا فَرَقۡنَٰهُ لِتَقۡرَأَهُۥ عَلَى ٱلنَّاسِ عَلَىٰ مُكۡثٖ وَنَزَّلۡنَٰهُ تَنزِيلٗا﴾", "en": "\"Quran\" comes from gathering together what was scattered. On the surface, it gathers the surahs and verses; looked at more deeply, it gathers everything people need for their life here and their return — all that brings them to the next world: \"We have neglected nothing in the Book\", \"a detailed explanation of everything\".\n'Atiyyah ibn al-Aswad told Ibn 'Abbas of a doubt in his heart: Allah says the Quran came down in the month of Ramadan, \"on the Night of Decree\", \"on a blessed night\" — yet it came down in every month of the year. Ibn 'Abbas answered: the blessed night is the Night of Decree, and the Night of Decree is in Ramadan; on it the Quran was sent down all at once to the Frequented House, and then revealed to Muhammad ﷺ piece by piece — \"a Quran We divided, that you may recite it to people at intervals\".", "ar": "«القرآن» أصله من القَرْء، أي ضمّ ما كان متفرّقًا؛ فسُمّي بذلك — بالنظر الجليّ — لأنه جامعٌ للسور والآيات، وبنظرٍ أدقّ لأنه جمع كلّ ما يحتاج إليه الناس من أمر معاشهم ومعادهم ممّا يتبلّغون به إلى الآخرة: ﴿مَّا فَرَّطۡنَا فِي ٱلۡكِتَٰبِ مِن شَيۡءٖۚ﴾، ﴿وَتَفۡصِيلَ كُلِّ شَيۡءٖ﴾.\nوقال عطيّة بن الأسود لابن عباس: في نفسي شيء: قال ﴿شَهۡرُ رَمَضَانَ ٱلَّذِيٓ أُنزِلَ فِيهِ ٱلۡقُرۡءَانُ﴾، و﴿إِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةِ ٱلۡقَدۡرِ﴾، و﴿إِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةٖ مُّبَٰرَكَةٍۚ﴾، وقد أُنزل القرآن في جميع الشهور! فقال: الليلة المباركة ليلة القدر، وليلة القدر في رمضان؛ أُنزل فيها القرآن جملةً إلى البيت المعمور، ثم أُنزل على محمدٍ ﷺ رَسَلًا — مفرّقًا —، وعلى هذا قوله: ﴿وَقُرۡءَانٗا فَرَقۡنَٰهُ لِتَقۡرَأَهُۥ عَلَى ٱلنَّاسِ عَلَىٰ مُكۡثٖ وَنَزَّلۡنَٰهُ تَنزِيلٗا﴾.", "links": [{"ref": "97:1", "q": "﴿إِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةِ ٱلۡقَدۡرِ﴾", "en": "The Night of Decree", "ar": "ليلة القدر"}, {"ref": "44:3", "q": "﴿إِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةٖ مُّبَٰرَكَةٍۚ﴾", "en": "The blessed night", "ar": "الليلة المباركة"}, {"ref": "17:106", "q": "﴿وَقُرۡءَانٗا فَرَقۡنَٰهُ لِتَقۡرَأَهُۥ عَلَى ٱلنَّاسِ عَلَىٰ مُكۡثٖ﴾", "en": "Then revealed piece by piece", "ar": "ثم نزل مفرّقًا"}], "v": 1, "p": 391, "pe": 392, "sid": 392},
  {"a": [185, 185], "h": "\"Guidance, clear proofs of guidance, and the Criterion\" — the general, then the detail", "hAr": "﴿هُدٗى لِّلنَّاسِ وَبَيِّنَٰتٖ مِّنَ ٱلۡهُدَىٰ وَٱلۡفُرۡقَانِۚ﴾ — المجمل ثم المفصّل", "said": "إن قيل: إذا كان الهدى مقتضيا للبينات، فما فائدة ﴿وَبَيِّنَٰتٖ مِّنَ ٱلۡهُدَىٰ﴾؟ قيل: القرآن يهدي على ضربين، أحدهما أن يدل على سبيل المجمل، والثاني: على سبيل التفصيل، فبين أن فيه هدى على الجملة، وبينات أي ما يوضح ويكشف على سبيل التفصيل، ففرق بين الحق والباطل، فصار ذكر البينات والفرقان بعد الهدى ذكر الخاص بعد العام ... والفرقان مصدر في الأصل [كالغفران والكفران] وسمي به القرآن لكونه فارقا بين الحق والباطل في الاعتقاد والصدق والكذب في المقال، والجميل والقبيح في الأفعال", "en": "If it is \"guidance\", why add \"clear proofs of guidance\"? Because the Quran guides in two ways: in general, pointing the way; and in detail, explaining and uncovering, so that true and false are separated. \"Guidance\" is the general; \"clear proofs\" and \"the Criterion\" are the particular, named after it.\nFurqan, \"the Criterion\", is at root a verbal noun, \"separating\"; the Quran is called by it because it separates the true from the false in belief, the true from the lying in speech, and the beautiful from the ugly in deeds.", "ar": "إذا كان الهدى يقتضي البيّنات فما فائدة ﴿وَبَيِّنَٰتٖ مِّنَ ٱلۡهُدَىٰ﴾؟ قيل: القرآن يهدي على ضربين: على سبيل الإجمال، وعلى سبيل التفصيل؛ فبيّن أن فيه هدًى على الجملة، وبيّناتٍ توضّح وتكشف على سبيل التفصيل، ففرّق بين الحقّ والباطل؛ فصار ذكر البيّنات والفرقان بعد الهدى ذكرَ الخاصّ بعد العامّ.\nو«الفرقان» مصدرٌ في الأصل كالغفران والكفران، وسُمّي به القرآن لكونه فارقًا بين الحقّ والباطل في الاعتقاد، والصدق والكذب في المقال، والجميل والقبيح في الأفعال.", "links": [{"ref": "25:1", "q": "﴿تَبَارَكَ ٱلَّذِي نَزَّلَ ٱلۡفُرۡقَانَ عَلَىٰ عَبۡدِهِۦ لِيَكُونَ لِلۡعَٰلَمِينَ نَذِيرًا﴾", "en": "The Criterion", "ar": "الفرقان"}, {"ref": "3:138", "q": "﴿هَٰذَا بَيَانٞ لِّلنَّاسِ وَهُدٗى وَمَوۡعِظَةٞ لِّلۡمُتَّقِينَ﴾", "en": "Explanation and guidance", "ar": "بيانٌ وهدى"}], "v": 1, "p": 392, "pe": 393, "sid": 393},
  {"a": [185, 185], "h": "\"Allah wants ease for you, not hardship\" — and the fast itself is the greater ease", "hAr": "﴿يُرِيدُ ٱللَّهُ بِكُمُ ٱلۡيُسۡرَ وَلَا يُرِيدُ بِكُمُ ٱلۡعُسۡرَ﴾ — والصوم نفسه أعظم اليسرين", "said": "وذكر الفقهاء أن إرادة اليسر هي مما رخص للمسافر والمريض، وذهب غيرهم إلى أن إرادة الله عز وجل اليسر لمن أوجب عليه الصوم ... كما هي للمفطر والصائم جميعا، ففي الصوم أعظم اليسرين، وعلى هذا قال الأعرابي: \" أقصد البلد المبارك لأصوم هذا الشهر المبارك \"، فقيل له: أفي هذا الحر؟ فقال: \" من الحر أفر \" وقيل لآخر: أتكد نفسك في العبادة، فقال: \" راحتها أريد، فإذن في إيجاب \" الله تعالى الصوم أعظم اليسرين ... ﴿وَلِتُكَبِّرُواْ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡ﴾ ولم يرد به التفوه بلفظ التكبير فقط، بل أراد معرفة كبريائه وعظمته وإن كان فيه دلالة أن التكبير مستحب", "en": "The jurists take \"ease\" to be the permission for the traveller and the sick to break the fast. Others go further: Allah wants ease for everyone He obliged to fast — for the one who breaks it and for the one who keeps it — and in the fast itself lies the greater of the two eases. A Bedouin said, \"I am going to the blessed city to fast this blessed month.\" \"In this heat?\" he was asked. \"It is from the heat that I am fleeing.\" Another, told \"you wear yourself out with worship\", replied: \"It is my soul's rest that I want.\" So in making fasting obligatory, Allah gave the greater ease.\n\"And magnify Allah for guiding you\" — not only saying \"Allahu akbar\" with the tongue, but knowing His greatness and majesty; though the verse also shows that saying the takbir is recommended.", "ar": "قال الفقهاء: إرادة اليسر ما رُخّص فيه للمسافر والمريض. وذهب غيرهم إلى أن إرادة الله اليسر لكلّ من أوجب عليه الصوم — للمفطر والصائم جميعًا —، ففي الصوم أعظم اليسرين. وعلى هذا قال الأعرابيّ: «أقصد البلد المبارك لأصوم هذا الشهر المبارك»، فقيل له: أفي هذا الحرّ؟ فقال: «من الحرّ أفرّ»؛ وقيل لآخر: أتكدّ نفسك في العبادة؟ فقال: «راحتَها أريد». فإذن في إيجاب الله الصوم أعظم اليسرين.\nو﴿وَلِتُكَبِّرُواْ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡ﴾: لم يُرد التفوّه بلفظ التكبير فقط، بل معرفة كبريائه وعظمته، وإن كان فيه دلالةٌ على استحباب التكبير.", "links": [{"ref": "9:81", "q": "﴿قُلۡ نَارُ جَهَنَّمَ أَشَدُّ حَرّٗاۚ لَّوۡ كَانُواْ يَفۡقَهُونَ﴾", "en": "\"It is from the heat that I flee\"", "ar": "«من الحرّ أفرّ»"}, {"ref": "4:28", "q": "﴿يُرِيدُ ٱللَّهُ أَن يُخَفِّفَ عَنكُمۡۚ وَخُلِقَ ٱلۡإِنسَٰنُ ضَعِيفٗا﴾", "en": "Allah wants to lighten your load", "ar": "يريد الله أن يخفّف عنكم"}, {"ref": "2:216", "q": "﴿وَعَسَىٰٓ أَن تَكۡرَهُواْ شَيۡـٔٗا وَهُوَ خَيۡرٞ لَّكُمۡۖ﴾", "en": "Real ease is not what feels easy", "ar": "اليسر الحقيقيّ غير ما تستخفّه النفس"}], "v": 1, "p": 394, "pe": 395, "sid": 395},
  {"a": [186, 186], "h": "\"I am near\" — why this verse stands in the middle of the fasting verses", "hAr": "﴿فَإِنِّي قَرِيبٌۖ﴾ — لماذا جاءت هذه الآية وسط آيات الصيام", "said": "قيل بل هي من تمام الآية الأولى، لأنه لما حث على تكبيره وشكره على ما قيضه لهم من إتمام الصوم، بين أن الذي تذكرونه وتشكرونه قريب منكم ومجيب لكم إذا دعوتموه، ثم تمم ما بقي من أحكام الصوم، ولم يرد بالقرب ههنا القرب المكاني، وإنما ذلك قربه تقتضيه إفضاله ووجود آثاره المشار إليها بقوله: ﴿وَنَحۡنُ أَقۡرَبُ إِلَيۡهِ مِنۡ حَبۡلِ ٱلۡوَرِيدِ﴾", "en": "This verse about prayer sits between two verses of fasting rulings — why? Ar-Raghib: it completes the verse before. Having urged the fasting believers to magnify Allah and thank Him for helping them complete the fast, He tells them that the One they remember and thank is near to them and answers them when they call — and then goes on with the remaining rulings of the fast. The nearness is not of place; it is the nearness of His generosity and of His works all around us — \"We are nearer to him than his jugular vein\". It is reported that the Prophet ﷺ was asked about Allah's nearness, and this was revealed; and He promised: \"call on Me, I will answer you\".", "ar": "كيف فُصل بهذه الآية بين آيتين في أحكام رمضان؟ قال الراغب: بل هي من تمام الآية قبلها: لمّا حثّ على تكبيره وشكره على ما قيّضه لهم من إتمام الصوم، بيّن أن الذي تذكرونه وتشكرونه قريبٌ منكم مجيبٌ لكم إذا دعوتموه، ثم تمّم ما بقي من أحكام الصوم. ولم يُرد القرب المكانيّ، بل قربه الذي يقتضيه إفضاله ووجود آثاره: ﴿وَنَحۡنُ أَقۡرَبُ إِلَيۡهِ مِنۡ حَبۡلِ ٱلۡوَرِيدِ﴾. ورُوي أن النبي ﷺ سُئل عن ذلك فنزلت، وضمن أنهم إذا دعوه أجابهم: ﴿ٱدۡعُونِيٓ أَسۡتَجِبۡ لَكُمۡۚ﴾.", "links": [{"ref": "50:16", "q": "﴿وَنَحۡنُ أَقۡرَبُ إِلَيۡهِ مِنۡ حَبۡلِ ٱلۡوَرِيدِ﴾", "en": "Nearness that is not of place", "ar": "قربٌ ليس مكانيًّا"}, {"ref": "40:60", "q": "﴿وَقَالَ رَبُّكُمُ ٱدۡعُونِيٓ أَسۡتَجِبۡ لَكُمۡۚ﴾", "en": "The promise of an answer", "ar": "وعد الإجابة"}], "v": 1, "p": 395, "pe": 395, "sid": 396},
  {"a": [186, 186], "h": "Why some prayers seem unanswered — whose prayer is promised an answer", "hAr": "لماذا يبدو أن بعض الدعاء لا يُجاب — ولمن ضُمنت الإجابة", "said": "إن قيل: قد ضمن في الآيتين أن من يدعوه يجيبه، وكم رأينا من داع له لا يجاب؟، قيل: إنه ضمن الإجابة لعباده، ولم يرد بالعباد من ذكرهم بقوله: ﴿إِن كُلُّ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ إِلَّآ ءَاتِي ٱلرَّحۡمَٰنِ عَبۡدٗا﴾، وإنما عني بهم الموصوفين ... في قوله- عز وجل- ﴿إِنَّ عِبَادِي لَيۡسَ لَكَ عَلَيۡهِمۡ سُلۡطَٰنٌ﴾ ... ولدعائهم شرائط، وهي أن تدعو بأحسن الأسماء كما قال الله تعالى: ﴿وَلِلَّهِ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰ فَٱدۡعُوهُ بِهَاۖ﴾، ويخلص له النية [و]الافتقار ولا يرغب إليه فيما تنزه الأكابر عن مسئلة مثله ولا ما يستعين به على معاداته، وأن يعلم أن نعمته فيما يمنعه من دنياه كنعمته فيما أعطاه، ومعلوم أن من هذا حاله مجاب الدعوة", "en": "Allah promises in two verses to answer whoever calls Him — yet how often we see people call and not be answered! Ar-Raghib: the promise is to \"My servants\" — not \"servants\" in the sense in which every creature is His servant (\"everyone in the heavens and the earth comes to the Most Merciful as a servant\"), but those described as His servants in the full sense: \"over My servants you have no power\", \"the servants of the Most Merciful who walk the earth humbly\".\nAnd their calling has conditions: to call Him by His most beautiful names; to be sincere, and truly in need of Him; not to ask for what the noble would be ashamed to ask, nor for anything to be used against Him; and to know that His favour in what He holds back from you of this world is like His favour in what He gives. Whoever is like that is answered — among those the Prophet ﷺ described: many a man in worn-out clothes whom no one notices, who, if he swore by Allah, Allah would fulfil it.\n\"So let them respond to Me\" — istijabah is seeking to answer Him: when His servants try, as far as they can, to answer His call, He is pleased with them. \"And believe in Me\": responding is the limbs following His commands; faith is what the heart holds — and here the faith meant is the fuller faith that comes after responding: \"the believers are those whose hearts tremble when Allah is mentioned\".", "ar": "فإن قيل: ضمن الله الإجابة لمن يدعوه، وكم رأينا من داعٍ لا يُجاب! قيل: ضمنها لـ«عباده»، ولم يُرد بهم من ذكرهم بقوله ﴿إِن كُلُّ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ إِلَّآ ءَاتِي ٱلرَّحۡمَٰنِ عَبۡدٗا﴾، بل الموصوفين بقوله ﴿إِنَّ عِبَادِي لَيۡسَ لَكَ عَلَيۡهِمۡ سُلۡطَٰنٌ﴾، و﴿وَعِبَادُ ٱلرَّحۡمَٰنِ ٱلَّذِينَ يَمۡشُونَ عَلَى ٱلۡأَرۡضِ هَوۡنٗا﴾.\nولدعائهم شرائط: أن يدعو بأحسن الأسماء — ﴿وَلِلَّهِ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰ فَٱدۡعُوهُ بِهَاۖ﴾ —، ويُخلص له النيّة والافتقار، ولا يرغب إليه فيما يتنزّه الأكابر عن مسألة مثله، ولا فيما يستعين به على معاداته، وأن يعلم أن نعمته فيما يمنعه من دنياه كنعمته فيما أعطاه. ومن هذا حاله فهو مجاب الدعوة، ومن جملة من وصفهم النبي ﷺ: «ربّ ذي طِمرين لا يُؤبه له لو أقسم على الله لأبرّه».\nو﴿فَلۡيَسۡتَجِيبُواْ لِي﴾: الاستجابة طلب الإجابة، فمتى تحرّى العباد إجابته بقدر وسعهم رضي عنهم. و﴿وَلۡيُؤۡمِنُواْ بِي﴾: الإجابة ارتسام أوامره ونواهيه بالجوارح، والإيمان اعتقاد القلوب — والمراد هنا الإيمان المذكور في ﴿إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ﴾، وهو بعد الإجابة.", "links": [{"ref": "7:180", "q": "﴿وَلِلَّهِ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰ فَٱدۡعُوهُ بِهَاۖ﴾", "en": "Calling Him by His names", "ar": "دعاؤه بأسمائه"}, {"ref": "25:63", "q": "﴿وَعِبَادُ ٱلرَّحۡمَٰنِ ٱلَّذِينَ يَمۡشُونَ عَلَى ٱلۡأَرۡضِ هَوۡنٗا﴾", "en": "\"My servants\" in the full sense", "ar": "«عبادي» بالمعنى التامّ"}, {"ref": "2:216", "q": "﴿وَعَسَىٰٓ أَن تَكۡرَهُواْ شَيۡـٔٗا وَهُوَ خَيۡرٞ لَّكُمۡۖ﴾", "en": "The favour in what is withheld", "ar": "النعمة فيما يُمنع"}], "v": 1, "p": 396, "pe": 396, "sid": 397},
  {"a": [187, 187], "h": "\"They are a garment for you, and you are a garment for them\"", "hAr": "﴿هُنَّ لِبَاسٞ لَّكُمۡ وَأَنتُمۡ لِبَاسٞ لَّهُنَّۗ﴾", "said": "وقوله: ﴿هُنَّ لِبَاسٞ لَّكُمۡ وَأَنتُمۡ لِبَاسٞ لَّهُنَّۗ﴾ جعل اللباس كناية عن الزوج، لكونه سترا لنفسه ولزوجه أن يظهر منهما سوء، كما أن اللباس يمنع أن تبدو السوءة، وعلى ذلك جعلت المرأة إزارا، وسمي النكاح حصنا، لكونه حصينا لذويه عن تعاطي القبيح", "en": "Rafath is speech that alludes to intimacy, and then a gentle word for intimacy itself. It was lawful now on the nights of the fast — for, it is reported, in the early days a fasting person who fell asleep after sunset could not eat or be with his wife until the next night; one of the Ansar fell asleep before eating and was found exhausted the next day, and this verse came down.\n\"They are a garment for you, and you for them\": each spouse covers the other — keeping anything shameful from showing in either of them — as a garment keeps the body from being exposed. That is why a wife was called an izar, a covering, and marriage a hisn, a fortress: it guards those in it from what is ugly.", "ar": "«الرفث» كلّ كلامٍ يتضمّن ذكر الجماع، ثم جُعل كنايةً عنه. ورُوي أن المباحات كانت تحرم على الصائم بعد الرقاد، وأن رجلًا من الأنصار نام قبل أن يطعم، فرآه النبي ﷺ من الغد مجهودًا، فنزلت الآية.\nو﴿هُنَّ لِبَاسٞ لَّكُمۡ وَأَنتُمۡ لِبَاسٞ لَّهُنَّۗ﴾: جعل اللباس كنايةً عن الزوج، لأن كلًّا منهما سترٌ لنفسه ولزوجه أن يظهر منهما سوء، كما يمنع اللباس أن تبدو السوءة؛ ولذلك جُعلت المرأة إزارًا، وسُمّي النكاح حِصنًا لكونه يحصّن أهله عن تعاطي القبيح.", "links": [{"ref": "30:21", "q": "﴿وَمِنۡ ءَايَٰتِهِۦٓ أَنۡ خَلَقَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَٰجٗا لِّتَسۡكُنُوٓاْ إِلَيۡهَا﴾", "en": "Spouses as rest and cover", "ar": "الزوجان سكنٌ وستر"}, {"ref": "23:5-6", "q": "﴿وَٱلَّذِينَ هُمۡ لِفُرُوجِهِمۡ حَٰفِظُونَ ۝ إِلَّا عَلَىٰٓ أَزۡوَٰجِهِمۡ﴾", "en": "Marriage as a fortress", "ar": "النكاح حِصن"}], "v": 1, "p": 398, "pe": 398, "sid": 399},
  {"a": [187, 187], "h": "\"Allah knew you were betraying yourselves\" — and \"seek what Allah has written for you\"", "hAr": "﴿عَلِمَ ٱللَّهُ أَنَّكُمۡ كُنتُمۡ تَخۡتَانُونَ أَنفُسَكُمۡ﴾ — و﴿وَٱبۡتَغُواْ مَا كَتَبَ ٱللَّهُ لَكُمۡۚ﴾", "said": "والاختيان مراودة الخيانة وتخصيصه من دون قوله: (تخونون) لفائدة، وهي أن المخاطبين لم يكونوا كلهم خانوا وكلهم أو جلهم قد اختانوا، لأن الاختيان هو أن تتحرك الشهوة وتدعوه، ولذلك خص لفظ النفس المعنية بقوله: ﴿إِنَّ ٱلنَّفۡسَ لَأَمَّارَةُۢ بِٱلسُّوٓءِ﴾، وكفى للتنبيه على اختيان النفس شهادة من خلقها بذلك علما بقوله تعالى: ﴿عَلِمَ ٱللَّهُ أَنَّكُمۡ كُنتُمۡ تَخۡتَانُونَ أَنفُسَكُمۡ﴾ ... وقوله تعالى: ﴿وَٱبۡتَغُواْ مَا كَتَبَ ٱللَّهُ﴾ إشارة في تحري النكاح إلى لطيفة، وهي أن الله تعالى جعل لنا شهوة النكاح لبقاء نوع الإنسان إلى غاية، كما جعل لنا شهوة الطعام لبقاء أشخاصنا إلى غاية، فحق الإنسان أن يتحرى بالنكاح ما جعل الله لنا على حسب ما يقتضيه العقل والديانة، فمتى تحرى به حفظ النسل وحصن النفس على الوجه المشروع، فقد ابتغى ما كتب الله له", "en": "\"Betraying yourselves\" is ikhtiyan, not khiyanah: not all of them had actually betrayed, but all or most had been tempted to — ikhtiyan is desire stirring and calling. That is why it says \"yourselves\": the soul that commands evil. And there is no plainer warning about the soul's treachery than the testimony of the One who created it: \"Allah knew\".\n\"And seek what Allah has written for you\" holds a fine point about marriage. Allah gave us the desire for marriage to keep the human race going to its appointed end, as He gave us the desire for food to keep each of us alive to his appointed end. So a person should seek in marriage what Allah made it for, as reason and religion direct: whoever seeks in it children and a guarded soul, in the lawful way, has \"sought what Allah has written for him\" — which is why some said it means the child.\nThe \"white thread and black thread\" are the white of day and the black of night: 'Adi ibn Hatim put a white and a black cord under his pillow and kept eating until he could tell them apart, and the Prophet ﷺ told him, smiling, \"your pillow must be wide indeed! It is the blackness of night and the whiteness of day.\"", "ar": "﴿تَخۡتَانُونَ أَنفُسَكُمۡ﴾ ولم يقل «تخونون»: لأن المخاطبين لم يخونوا كلّهم، ولكن كلّهم أو جُلّهم قد «اختانوا» — والاختيان أن تتحرّك الشهوة وتدعو؛ ولذلك خُصّ لفظ النفس، وهي ﴿لَأَمَّارَةُۢ بِٱلسُّوٓءِ﴾؛ وكفى تنبيهًا على اختيان النفس شهادةُ من خلقها: ﴿عَلِمَ ٱللَّهُ﴾.\nو﴿وَٱبۡتَغُواْ مَا كَتَبَ ٱللَّهُ لَكُمۡۚ﴾ فيه لطيفةٌ في النكاح: جعل الله لنا شهوة النكاح لبقاء نوع الإنسان إلى غاية، كما جعل لنا شهوة الطعام لبقاء أشخاصنا إلى غاية؛ فحقّ الإنسان أن يتحرّى بالنكاح ما جعله الله له بحسب ما يقتضيه العقل والديانة: فمتى تحرّى به حفظ النسل وتحصين النفس على الوجه المشروع فقد ابتغى ما كتب الله له — ولهذا قال بعضهم: عنى الولد.\nو«الخيط الأبيض» بياض النهار، و«الخيط الأسود» سواد الليل؛ ورُوي أن عديّ بن حاتم عمد إلى عقالين أبيض وأسود فجعل ينظر إليهما ويأكل حتى يتبيّن أحدهما من الآخر، فأخبر النبيَّ ﷺ فقال: «إنك لعريض الوساد! إنما ذاك سواد الليل وبياض النهار».", "links": [{"ref": "12:53", "q": "﴿إِنَّ ٱلنَّفۡسَ لَأَمَّارَةُۢ بِٱلسُّوٓءِ﴾", "en": "The soul that tempts", "ar": "النفس التي تُراود"}, {"ref": "16:72", "q": "﴿وَٱللَّهُ جَعَلَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَٰجٗا وَجَعَلَ لَكُم مِّنۡ أَزۡوَٰجِكُم بَنِينَ وَحَفَدَةٗ﴾", "en": "What marriage is for", "ar": "ما جُعل له النكاح"}, {"ref": "2:187", "q": "﴿ثُمَّ أَتِمُّواْ ٱلصِّيَامَ إِلَى ٱلَّيۡلِۚ﴾", "en": "The boundary of the fast", "ar": "حدّ الصوم"}], "v": 1, "p": 398, "pe": 399, "sid": 399},
  {"a": [188, 188], "h": "\"Do not devour one another's wealth, nor bribe the judges\" — a judge's ruling does not make a wrong right", "hAr": "﴿وَلَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم بَيۡنَكُم بِٱلۡبَٰطِلِ وَتُدۡلُواْ بِهَآ إِلَى ٱلۡحُكَّامِ﴾ — حكم القاضي لا يجعل الباطل حقًّا", "said": "والأكل عبارة عن الإنفاق، إذ هو أهم ما يصرف إليه المال، وأكل المال بالباطل صرفه إلى ما ينافيه الحق، وهو التبذير والإسراف قليلا كان الإنفاق أو كثيرا، ولهذا قيل: (رب إنفاق قليل هو إسراف، وكثير هو اقتصاد) ... وكما نهي عن تبذير الأموال نهى أن يدلي بها إلى الحكام على سبيل الرشوة، وتوصلا إلى اقتطاع أموال الناس ... وقوله: ﴿وَأَنتُمۡ تَعۡلَمُونَ﴾ أي إن خفي علمكم على الناس، فإنه لا يخفى عليكم تنبيها أن الاعتبار بما عليه الأمر في نفسه وما علمتم منه لا بما يظهر، ونبه - عليه السلام - على ذلك بقوله: (إنكم تختصمون إلي، ولعل بعضكم ألحن بحجته من بعض، فمن حكمت له بشيء من حق أخيه، فلا يأخذن منه قليلا ولا كثيرا، فإنما أقطع له قطعة من النار)", "en": "\"Eating\" wealth stands for spending it, the chief use wealth is put to; \"eating it wrongfully\" is spending it on what right forbids — squandering and extravagance, whether the amount is small or large. As it was said, \"many a small spending is extravagance, and many a large one is moderation.\"\nAnd \"do not let it down (tudlu) to the judges\" — idla' is lowering a bucket into a well, then any means of reaching something: do not use your wealth as a bribe to the judges, to cut off a share of other people's property. (Or: do not seize others' wealth by force or fraud, knowing that when they go to court, the judge cannot rule against you for lack of evidence.)\n\"While you know\": it may be hidden from people, but not from you. What counts is how the matter really is, and what you know of it — not how it appears. The Prophet ﷺ said: \"You bring your disputes to me, and one of you may be more eloquent in his case than the other. If I rule for someone that he should have something that is his brother's right, let him not take it — for I am only cutting off for him a piece of the Fire.\"", "ar": "«الأكل» هنا عبارةٌ عن الإنفاق، إذ هو أهمّ ما يُصرف إليه المال؛ و«أكل المال بالباطل» صرفه إلى ما ينافيه الحقّ — وهو التبذير والإسراف، قليلًا كان الإنفاق أو كثيرًا —؛ ولهذا قيل: «ربّ إنفاقٍ قليلٍ هو إسراف، وكثيرٍ هو اقتصاد».\nو«الإدلاء» إرسال الدلو في البئر، ثم استُعير للتوصّل إلى الشيء: فكما نهى عن تبذير الأموال نهى أن يُدلى بها إلى الحكّام رشوةً وتوصّلًا إلى اقتطاع أموال الناس. (وقيل: لا يأكل بعضكم مال بعضٍ غصبًا أو خيانةً فيُلجئهم إلى المرافعة، فلا يُحكم عليكم لعدم البيّنة.)\nو﴿وَأَنتُمۡ تَعۡلَمُونَ﴾: إن خفي على الناس فلا يخفى عليكم؛ تنبيهًا أن الاعتبار بما عليه الأمر في نفسه وبما علمتم منه، لا بما يظهر. ونبّه ﷺ على ذلك بقوله: «إنكم تختصمون إليّ، ولعلّ بعضكم ألحن بحجّته من بعض، فمن حكمتُ له بشيءٍ من حقّ أخيه فلا يأخذنّ منه شيئًا، فإنما أقطع له قطعةً من النار».", "links": [{"ref": "4:29", "q": "﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم بَيۡنَكُم بِٱلۡبَٰطِلِ إِلَّآ أَن تَكُونَ تِجَٰرَةً عَن تَرَاضٖ مِّنكُمۡۚ﴾", "en": "Wealth changes hands only by fair consent", "ar": "لا ينتقل المال إلا بتراضٍ"}, {"ref": "25:67", "q": "﴿وَٱلَّذِينَ إِذَآ أَنفَقُواْ لَمۡ يُسۡرِفُواْ وَلَمۡ يَقۡتُرُواْ وَكَانَ بَيۡنَ ذَٰلِكَ قَوَامٗا﴾", "en": "Moderation in spending", "ar": "القوام في الإنفاق"}, {"ref": "17:26-27", "q": "﴿وَلَا تُبَذِّرۡ تَبۡذِيرًا ۝ إِنَّ ٱلۡمُبَذِّرِينَ كَانُوٓاْ إِخۡوَٰنَ ٱلشَّيَٰطِينِۖ﴾", "en": "Squandering", "ar": "التبذير"}], "v": 1, "p": 400, "pe": 401, "sid": 401},
  {"a": [189, 189], "h": "\"They ask you about the new moons\" — time made visible in the sky", "hAr": "﴿يَسۡـَٔلُونَكَ عَنِ ٱلۡأَهِلَّةِۖ﴾ — الوقت مرسومًا في السماء", "said": "المواقيت: جمع ميقات ... والوقت الزمان المفروض للعمل ومعنى مواقيت للناس أي ما يتعلق به من أمور معاملاتهم ومصالحهم، كقوله تعالى: ﴿هُوَ ٱلَّذِي جَعَلَ ٱلشَّمۡسَ ضِيَآءٗ وَٱلۡقَمَرَ نُورٗا وَقَدَّرَهُۥ مَنَازِلَ لِتَعۡلَمُواْ عَدَدَ ٱلسِّنِينَ وَٱلۡحِسَابَۚ﴾ ونبه بذكر الحج على ما يتعلق به من العبادات ... وقد كان سئل - عليه السلام - عن فائدة زيادة الهلال ونقصانه، فأنزل الله تعالى هذه الآية منبها على أظهر فائدته للحس وأبينها له", "en": "Mawaqit, \"appointed times\", is the plural of miqat, from waqt. He separates three words: duration in the absolute is the whole unbroken span of time; zaman is a portion cut out of it; waqt is the time set for a particular act.\nThe Prophet ﷺ was asked what benefit there is in the moon growing and shrinking, and the answer points to its plainest benefit, the one anyone can see: it marks times for people — their dealings and their interests — as \"He made the sun a radiance and the moon a light, and measured out its stages, so that you might know the number of years and the reckoning\". Of the acts of worship tied to it, the Hajj is named, because the Hajj depends on a fixed time more than any other worship: it can be performed, and made up, only in its season.", "ar": "«المواقيت» جمع ميقات، من الوقت. والمدّة المطلقة امتدادٌ متّصلٌ من مبدئه إلى غايته، و«الزمان» مدّةٌ مقسومةٌ منها، و«الوقت» الزمان المفروض للعمل.\nوقد سُئل ﷺ عن فائدة زيادة الهلال ونقصانه، فنزلت الآية منبّهةً على أظهر فوائده للحسّ وأبينها: ﴿مَوَٰقِيتُ لِلنَّاسِ﴾ — ما يتعلّق به من معاملاتهم ومصالحهم —، كقوله: ﴿هُوَ ٱلَّذِي جَعَلَ ٱلشَّمۡسَ ضِيَآءٗ وَٱلۡقَمَرَ نُورٗا وَقَدَّرَهُۥ مَنَازِلَ لِتَعۡلَمُواْ عَدَدَ ٱلسِّنِينَ وَٱلۡحِسَابَۚ﴾. ونبّه بذكر الحجّ على ما يتعلّق به من العبادات، وذكر أعظمها أثرًا، فالحجّ يُراعى في أدائه وقضائه الوقت المعلوم، بخلاف سائر العبادات.", "links": [{"ref": "10:5", "q": "﴿هُوَ ٱلَّذِي جَعَلَ ٱلشَّمۡسَ ضِيَآءٗ وَٱلۡقَمَرَ نُورٗا وَقَدَّرَهُۥ مَنَازِلَ لِتَعۡلَمُواْ عَدَدَ ٱلسِّنِينَ وَٱلۡحِسَابَۚ﴾", "en": "The moon's stages for counting", "ar": "منازل القمر للحساب"}, {"ref": "9:36", "q": "﴿إِنَّ عِدَّةَ ٱلشُّهُورِ عِندَ ٱللَّهِ ٱثۡنَا عَشَرَ شَهۡرٗا﴾", "en": "The lunar year", "ar": "السنة القمريّة"}, {"ref": "2:197", "q": "﴿ٱلۡحَجُّ أَشۡهُرٞ مَّعۡلُومَٰتٞۚ﴾", "en": "The Hajj tied to its months", "ar": "الحجّ في أشهرٍ معلومات"}], "v": 1, "p": 401, "pe": 402, "sid": 402},
  {"a": [189, 189], "h": "\"Enter houses by their doors\" — two kinds of knowledge, and which one the Prophet ﷺ was sent with", "hAr": "﴿وَأۡتُواْ ٱلۡبُيُوتَ مِنۡ أَبۡوَٰبِهَاۚ﴾ — نوعا العلم، وأيّهما بُعث به النبيّ ﷺ", "said": "و \" أتى البيت من ظهره \" إذا طلب الأمر من غير وجهه وجعل ذلك مثلا لسؤالهم النبي - صلى الله عليه وسلم - عما هو ليس من العلم المختص بالنبوة، وأن ذلك عدول عن المنهج وذلك أن العلوم ضربان: دنيوي: يتعلق بأمر المعاش كمعرفة الصنايع ومعرفة الأجرام السماوية ومعرفة المعادن والنبات وطبائع الحيوانات، وقد جعل الله تعالى لنا سبيلا إلى معرفته على غير لسان نبيه محمد - عليه السلام -، وشرعي: وهو البر، ولا سبيل إلى أخذه إلا من جهته وهو أحكام التقوى، فلما جاءوا يسألون النبي - صلى الله عليه وسلم - عما أمكنهم معرفته من غير جهته أجابهم ثم بين لهم أن ليس البر ترك المنهج في سؤال النبي - عليه السلام - ما ليس هو مختصا بعلم نبوته ولكن البر هو تحري التقوى، وذلك يكون بالعلم والعمل المختصين بالدين", "en": "\"He came to the house by its door\" means he sought a thing the right way; \"he came to it from the back\" means the wrong way. Here, ar-Raghib says, it is a parable for asking the Prophet ﷺ about what is not the knowledge that prophethood brings.\nFor knowledge is of two kinds. Worldly knowledge concerns our livelihood — the crafts, the heavenly bodies, minerals, plants, the nature of animals — and Allah has given us ways to learn it other than through His Prophet. Religious knowledge is righteousness itself — the rulings of God-consciousness — and there is no way to it except through him. They came asking the Prophet about something they could have learned by other means; he answered them, and then they were told: righteousness is not leaving the right path by asking the Prophet about what is not his special knowledge; righteousness is seeking God-consciousness, through the knowledge and action that belong to the religion.\n(Others say the verse is about an old custom: some Arabs in ihram would not enter their houses by the door but climbed in from the back — and all of this can be included; but the first reading fits the start of the verse best.) \"Enter houses by their doors\": in every matter, seek the thing in its proper way; what is sought the wrong way is hard to reach. \"And be mindful of Allah\" — make that the mark of everything you seek; it is the road to success.", "ar": "يُقال «أتى البيت من بابه» إذا طلب الشيء من وجهه، و«أتاه من ظهره» إذا طلبه من غير وجهه؛ وجُعل ذلك مثلًا لسؤالهم النبيّ ﷺ عمّا ليس من العلم المختصّ بالنبوّة، وأن ذلك عدولٌ عن المنهج.\nفالعلوم ضربان: دنيويٌّ يتعلّق بأمر المعاش — كمعرفة الصنائع والأجرام السماويّة والمعادن والنبات وطبائع الحيوان —، وقد جعل الله لنا سبيلًا إلى معرفته على غير لسان نبيّه ﷺ؛ وشرعيٌّ — وهو البرّ، أحكام التقوى — لا سبيل إلى أخذه إلا من جهته. فلمّا جاؤوا يسألونه عمّا أمكنهم معرفته من غير جهته أجابهم، ثم بيّن أن البرّ ليس في ترك المنهج بسؤاله عمّا ليس مختصًّا بعلم نبوّته، ولكنّ البرّ تحرّي التقوى بالعلم والعمل المختصّين بالدين.\n(وقال بعض المفسّرين: كان من لم يكن من الحُمس إذا أحرم لم يدخل البيت من بابه بل من ظهره — وكلّ ذلك تتناوله الآية، لكنّ الأليق بأوّلها ما تقدّم.) و﴿وَأۡتُواْ ٱلۡبُيُوتَ مِنۡ أَبۡوَٰبِهَاۚ﴾: تحرّوا في كلّ عملٍ إتيان الشيء من وجهه، فما يُطلب من غير وجهه صعبٌ مناله؛ و﴿وَٱتَّقُواْ ٱللَّهَ﴾: اجعلوا التقوى شعاركم في كلّ ما تتحرّونه، فهي الذريعة إلى الفلاح.", "links": [{"ref": "67:26", "q": "﴿قُلۡ إِنَّمَا ٱلۡعِلۡمُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٞ مُّبِينٞ﴾", "en": "The Prophet's special knowledge: the warning", "ar": "علم النبيّ الخاصّ: النذارة"}, {"ref": "21:80", "q": "﴿وَعَلَّمۡنَٰهُ صَنۡعَةَ لَبُوسٖ لَّكُمۡ﴾", "en": "Crafts: knowledge of the world", "ar": "الصنائع: علم الدنيا"}, {"ref": "2:177", "q": "﴿وَلَٰكِنَّ ٱلۡبِرَّ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ﴾", "en": "What righteousness is", "ar": "ما البرّ"}], "v": 1, "p": 403, "pe": 403, "sid": 404},
  {"a": [190, 190], "h": "\"Fight those who fight you — and do not transgress\": the stages of calling people to the truth", "hAr": "﴿وَقَٰتِلُواْ فِي سَبِيلِ ٱللَّهِ ٱلَّذِينَ يُقَٰتِلُونَكُمۡ وَلَا تَعۡتَدُوٓاْۚ﴾ — مراتب الدعوة إلى الحقّ", "said": "وبيان ذلك أن من شرط الداعي إلى الحق أن يبينه ويدل عليه ويرفق، فإن اهتدى المدعو، وإلا أوعد، فإن أنجع ذلك وإلا عدل بعد إلى المحاسبة والمحاربة على ما تقتضيه السياسة، وعلى هذا قال بعضهم: \" لا أستعمل سوطي ما كفاني لساني ولا سيفي ما كفاني سوطي \" ... فكان النبي - صلى الله عليه وسلم - أمر في أول الأمر بالرفق والأناة، وأن يقتصر على الوعظ والمجادلة الحسنة، كما قال تعالى: ﴿ٱدۡعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلۡحِكۡمَةِ وَٱلۡمَوۡعِظَةِ ٱلۡحَسَنَةِۖ وَجَٰدِلۡهُم بِٱلَّتِي هِيَ أَحۡسَنُۚ﴾ ... فلما ظهرت آياته، وانتشرت بيناته، ورأى من أبى الإصغاء إلى الحق، واستمر على الضلال والإضلال أمر حينئذ بالمقاتلة أي المحاربة ... وكان هذا أمرا بعد أمر حسب مقتضى السياسة الإلهية ... ﴿وَلَا تَعۡتَدُوٓاْۚ﴾: نهي عام في مجاوزة كل حد حده الله تعالى، كالنهي عن قتل الصبيان والنساء ... ونبه بقوله: ﴿إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ﴾ أن اعتداء مرسوم الله وتجاوز حكمه في كل أمر مذموم", "en": "Scholars differed on whether this verse abrogated an earlier ruling or was itself abrogated. Ar-Raghib explains it another way — as a stage in a single method. The one who calls to the truth must first explain it, point to it, and be gentle. If the one called accepts guidance, good; if not, he is warned; if the warning works, good; if not, only then comes holding to account and fighting, as good governance requires. As a ruler once said: \"I do not use my whip while my tongue is enough, nor my sword while my whip is enough.\"\nSo the Prophet ﷺ was commanded at first to be gentle and patient, and to keep to admonition and the best kind of argument — \"call to the way of your Lord with wisdom and good counsel, and argue with them in the best way\". He kept to that for years, even when some Companions complained that they had been strong as idolaters and were humiliated as believers; he told them, \"I have been commanded to pardon — do not fight them today\". Only when his signs were plain and his proofs had spread, and he saw who refused to listen to the truth and persisted in error and in leading others astray, was he commanded to fight: a command after a command, as divine governance required.\n\"And do not transgress\" forbids crossing any limit Allah has set — such as killing children and women — and fighting for worldly gain or for power. \"Allah does not love transgressors\": crossing what Allah has drawn is blameworthy in every matter.", "ar": "اختُلف في حكم الآية: قيل ناسخةٌ لحكم العفو ومنسوخةٌ بقوله ﴿وَقَٰتِلُواْ ٱلۡمُشۡرِكِينَ كَآفَّةٗ﴾، وقيل: ليست بناسخةٍ ولا منسوخة. وبيانه أن من شرط الداعي إلى الحقّ أن يبيّنه ويدلّ عليه ويرفق؛ فإن اهتدى المدعوّ وإلا أوعده، فإن أنجع ذلك وإلا عدل بعدُ إلى المحاسبة والمحاربة على ما تقتضيه السياسة؛ وعلى هذا قال بعضهم: «لا أستعمل سوطي ما كفاني لساني، ولا سيفي ما كفاني سوطي».\nفكان النبيّ ﷺ مأمورًا في أوّل الأمر بالرفق والأناة، والاقتصار على الوعظ والمجادلة الحسنة: ﴿ٱدۡعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلۡحِكۡمَةِ وَٱلۡمَوۡعِظَةِ ٱلۡحَسَنَةِۖ وَجَٰدِلۡهُم بِٱلَّتِي هِيَ أَحۡسَنُۚ﴾، واستمرّ على ذلك حتى عاتبه بعض أصحابه: كنّا في عزٍّ ونحن مشركون، فلمّا آمنّا صرنا أذلّة! فقال: «أُمرتُ بالعفو فلا تقاتلوهم». فلمّا ظهرت آياته وانتشرت بيّناته، ورأى من أبى الإصغاء إلى الحقّ واستمرّ على الضلال والإضلال، أُمر حينئذٍ بالمحاربة — أمرًا بعد أمرٍ حسب مقتضى السياسة الإلهيّة.\nو﴿وَلَا تَعۡتَدُوٓاْۚ﴾: نهيٌ عامٌّ عن مجاوزة كلّ حدٍّ حدّه الله، كقتل الصبيان والنساء، وكالقتال ابتغاء عرض الدنيا وطلب الرئاسة. و﴿إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ﴾: تجاوز مرسوم الله في كلّ أمرٍ مذموم.", "links": [{"ref": "16:125", "q": "﴿ٱدۡعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلۡحِكۡمَةِ وَٱلۡمَوۡعِظَةِ ٱلۡحَسَنَةِۖ وَجَٰدِلۡهُم بِٱلَّتِي هِيَ أَحۡسَنُۚ﴾", "en": "The first stage: wisdom and argument", "ar": "المرتبة الأولى: الحكمة والمجادلة"}, {"ref": "22:39", "q": "﴿أُذِنَ لِلَّذِينَ يُقَٰتَلُونَ بِأَنَّهُمۡ ظُلِمُواْۚ﴾", "en": "The first permission to fight: because they were wronged", "ar": "أوّل الإذن بالقتال: لأنهم ظُلموا"}, {"ref": "4:77", "q": "﴿أَلَمۡ تَرَ إِلَى ٱلَّذِينَ قِيلَ لَهُمۡ كُفُّوٓاْ أَيۡدِيَكُمۡ وَأَقِيمُواْ ٱلصَّلَوٰةَ﴾", "en": "\"Hold back your hands\" — then the command changed", "ar": "«كفّوا أيديكم» ثم تغيّر الأمر"}], "v": 1, "p": 404, "pe": 405, "sid": 405},
  {"a": [191, 191], "h": "\"Persecution is worse than killing\" — two readings; and the sanctity of Makkah", "hAr": "﴿وَٱلۡفِتۡنَةُ أَشَدُّ مِنَ ٱلۡقَتۡلِۚ﴾ — قراءتان؛ وحرمة مكة", "said": "وأصل الفتنة إدخال الذهب النار للتصفية، يقال: فتنت الذهب أي اختبرته بالنار، ثم استعير لكل اختبار بأمر محض ... وجعل الفتنة لكل أمر مكروه المحتمل، فتارة استعير للشرك، وتارة للعذاب، وتارة للاختبار، ولما كان لفظ الفتنة والقتل ههنا مبهمين، قال بعضهم: معناه أن يفتن الإنسان في دينه، فيشرك أشد أي أوخم عاقبة من أن يقتل، فإن الأذية التي تنال المقتول محدودة، والأذية التي تنال المشرك بشركه غير محدودة، وقال بعضهم: إن معناه: أن يوقع الإنسان الفتنة أشد على الناس أي أعظم ضررا من أن يقتل في الحرم من يستحق القتل، وقال: وذلك رد على من استعظم قتل بعض المسلمين كافرا في الحرم ... وقوله: ﴿وَلَا تُقَٰتِلُوهُمۡ عِندَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ﴾ استثناء من قوله: ﴿وَٱقۡتُلُوهُمۡ حَيۡثُ ثَقِفۡتُمُوهُمۡ﴾، وهذا حكم عند أكثر الفقهاء فإنه لا يقاتل في الحرم إلا من قاتل، ويؤيد ذلك قوله - عليه السلام - يوم فتح مكة: \" إن مكة حرام حرمها الله - عز وجل - يوم خلق السماوات والأرض وإنما أحلت لي ساعة من نهار، ثم عادت حراما إلى يوم القيامة \"", "en": "Fitnah is first putting gold into fire to purify and test it; then any hard testing (\"do people think they will be left to say 'we believe' and not be tested?\"); then anything hateful that must be borne — used for idolatry, for punishment, and for trial.\n\"Fitnah is worse than killing\" has two readings. One: for a person to be turned from his religion into idolatry is worse in its end than being killed — the harm that reaches the one killed has a limit, the harm that reaches an idolater through his idolatry has none. Two: for someone to stir up persecution and strife among people is more harmful than killing, in the Sanctuary, one who deserves it — an answer to those who made much of some Muslims having killed a disbeliever there. That is why it goes on: \"fight them until there is no more fitnah\". (The disbelievers are to be expelled \"from where they expelled you\" — the believers had been driven out of their homes in Makkah.)\n\"Do not fight them at the Sacred Mosque unless they fight you there\": most jurists hold that no one may be fought in the Sanctuary except one who fights there. The Prophet ﷺ said on the day Makkah was opened: \"Makkah is sacred; Allah made it sacred the day He created the heavens and the earth. It was made lawful for me for one hour of one day, and then it returned to its sanctity until the Day of Resurrection.\"", "ar": "أصل «الفتنة» إدخال الذهب النار للتصفية، ثم استُعيرت لكلّ اختبار: ﴿أَحَسِبَ ٱلنَّاسُ أَن يُتۡرَكُوٓاْ أَن يَقُولُوٓاْ ءَامَنَّا وَهُمۡ لَا يُفۡتَنُونَ﴾، ثم لكلّ أمرٍ مكروهٍ يُحتمل: فاستُعيرت تارةً للشرك، وتارةً للعذاب، وتارةً للاختبار.\nو﴿وَٱلۡفِتۡنَةُ أَشَدُّ مِنَ ٱلۡقَتۡلِۚ﴾ فيه قولان: أن يُفتن الإنسان في دينه فيُشرك أوخم عاقبةً من أن يُقتل — فأذيّة المقتول محدودة، وأذيّة المشرك بشركه غير محدودة —؛ أو أن يوقع الإنسان الفتنة في الناس أعظم ضررًا من أن يُقتل في الحرم من يستحقّ القتل — ردًّا على من استعظم قتل بعض المسلمين كافرًا في الحرم —؛ ولهذا قال بعدها ﴿وَقَٰتِلُوهُمۡ حَتَّىٰ لَا تَكُونَ فِتۡنَةٞ﴾. و﴿وَأَخۡرِجُوهُم مِّنۡ حَيۡثُ أَخۡرَجُوكُمۡۚ﴾: فقد أُخرج المؤمنون من ديارهم بمكّة.\nو﴿وَلَا تُقَٰتِلُوهُمۡ عِندَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ حَتَّىٰ يُقَٰتِلُوكُمۡ فِيهِۖ﴾: استثناءٌ من ﴿وَٱقۡتُلُوهُمۡ حَيۡثُ ثَقِفۡتُمُوهُمۡ﴾، وهو حكمٌ عند أكثر الفقهاء: لا يُقاتَل في الحرم إلا من قاتل؛ ويؤيّده قوله ﷺ يوم الفتح: «إن مكّة حرّمها الله يوم خلق السماوات والأرض، وإنما أُحلّت لي ساعةً من نهار، ثم عادت حرامًا إلى يوم القيامة».", "links": [{"ref": "2:217", "q": "﴿يَسۡـَٔلُونَكَ عَنِ ٱلشَّهۡرِ ٱلۡحَرَامِ قِتَالٖ فِيهِۖ قُلۡ قِتَالٞ فِيهِ كَبِيرٞۚ﴾", "en": "\"Persecution is greater than killing\" — the event it answered", "ar": "«والفتنة أكبر من القتل» والحادثة التي أجابت عنها"}, {"ref": "22:40", "q": "﴿ٱلَّذِينَ أُخۡرِجُواْ مِن دِيَٰرِهِم بِغَيۡرِ حَقٍّ إِلَّآ أَن يَقُولُواْ رَبُّنَا ٱللَّهُۗ﴾", "en": "Driven from their homes for their faith", "ar": "أُخرجوا من ديارهم لإيمانهم"}, {"ref": "29:67", "q": "﴿أَوَلَمۡ يَرَوۡاْ أَنَّا جَعَلۡنَا حَرَمًا ءَامِنٗا﴾", "en": "The sanctuary made safe", "ar": "الحرم الآمن"}], "v": 1, "p": 405, "pe": 406, "sid": 406},
  {"a": [192, 193], "h": "\"If they stop, Allah is Forgiving\" — and fighting \"until there is no more persecution\"", "hAr": "﴿فَإِنِ ٱنتَهَوۡاْ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ﴾ — والقتال ﴿حَتَّىٰ لَا تَكُونَ فِتۡنَةٞ﴾", "said": "والنهي في موضوع أهل النحو من صيغة \" لا تفعل \" ... وفي موضوع أهل البرهان ما يقتضي الزجر عن الشيء سواء كان بلفظ \" أفعل \" أو \" لا تفعل \"، وهذا الخلاف من أجل أن النحوي يعتبر اللفظ قبل المعنى، وصاحب البرهان يعتبر المعنى قبل اللفظ، ونبه بالآية أن المنتهي عن الذنب يغفر له ما تقدم من ذنبه، وذلك عام في أمور الدنيا والآخرة إلا ما دلت الدلالة على الأخذ به من حقوق الآدميين، وعلى هذا قوله - عز وجل: ﴿قُل لِّلَّذِينَ كَفَرُوٓاْ إِن يَنتَهُواْ يُغۡفَرۡ لَهُم مَّا قَدۡ سَلَفَ﴾، وقوله عليه السلام: \" الإسلام يجب ما قبله \" ... أمر تعالى بالقتال لدفع الفتنة بعد أن بين أنها أعظم ضررا من القتل ... فقوله: ﴿حَتَّىٰ لَا تَكُونَ فِتۡنَةٞ﴾ كقوله: ﴿حَتَّىٰ تَضَعَ ٱلۡحَرۡبُ أَوۡزَارَهَاۚ﴾، وذلك إما بقتلهم أو بإسلامهم أو بانقيادهم وإعطاء الجزية حسب ما بينه الشرع، ﴿وَيَكُونَ ٱلدِّينُ لِلَّهِۖ﴾ قال ابن عباس: حتى يخلص التوحيد له ... ثم أعاد ذكر الانتهاء، فقال: ﴿فَإِنِ ٱنتَهَوۡاْ فَلَا عُدۡوَٰنَ إِلَّا عَلَى ٱلظَّٰلِمِينَ﴾", "en": "Intiha', \"stopping\", is restraining oneself; nuha, reason, comes from the same root, for reason restrains from what is ugly. (A grammarian calls \"do not do\" a prohibition by its form; a logician calls anything that restrains a prohibition, whatever its form — the grammarian looks at the words before the meaning, the logician at the meaning before the words.)\n\"If they stop, Allah is Forgiving, Merciful\": whoever stops his wrongdoing is forgiven what went before — in this world and the next — except for rights owed to other people that must still be settled. \"Say to those who disbelieve: if they stop, what is past will be forgiven them\"; \"Islam wipes away what came before it\".\nThen: fight them \"until there is no more fitnah\" — Allah commands fighting to remove persecution, having just said it is more harmful than killing; like \"until the war lays down its burdens\". It ends, ar-Raghib says, in one of the ways the law sets out: by their defeat, their Islam, or their submission and payment of the jizyah. \"And the religion is for Allah\": Ibn 'Abbas said, until the oneness of God is held purely for Him. \"And if they stop, there is no hostility except against the wrongdoers\" — no one crosses a limit except against one who has crossed it himself.", "ar": "«الانتهاء» الانزجار، و«النُّهى» العقل لأنه ينهى عن القبيح. (والنهي عند النحويّين صيغة «لا تفعل»، وعند أهل البرهان ما يقتضي الزجر بأيّ صيغة؛ لأن النحويّ يعتبر اللفظ قبل المعنى، وصاحب البرهان يعتبر المعنى قبل اللفظ.)\nو﴿فَإِنِ ٱنتَهَوۡاْ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ﴾: المنتهي عن الذنب يُغفر له ما تقدّم، في أمور الدنيا والآخرة، إلا ما دلّت الدلالة على الأخذ به من حقوق الآدميّين: ﴿قُل لِّلَّذِينَ كَفَرُوٓاْ إِن يَنتَهُواْ يُغۡفَرۡ لَهُم مَّا قَدۡ سَلَفَ﴾، و«الإسلام يجُبّ ما قبله».\nو﴿وَقَٰتِلُوهُمۡ حَتَّىٰ لَا تَكُونَ فِتۡنَةٞ﴾: أمر بالقتال لدفع الفتنة بعد أن بيّن أنها أعظم ضررًا من القتل، كقوله ﴿حَتَّىٰ تَضَعَ ٱلۡحَرۡبُ أَوۡزَارَهَاۚ﴾؛ وذلك — كما قال — إمّا بقتلهم، أو بإسلامهم، أو بانقيادهم وإعطاء الجزية حسب ما بيّنه الشرع. و﴿وَيَكُونَ ٱلدِّينُ لِلَّهِۖ﴾: قال ابن عباس: حتى يخلص التوحيد له. ثم أعاد ذكر الانتهاء: ﴿فَإِنِ ٱنتَهَوۡاْ فَلَا عُدۡوَٰنَ إِلَّا عَلَى ٱلظَّٰلِمِينَ﴾ — فلا يُتجاوز الحدّ إلا مع من يتجاوزه بفعله.", "links": [{"ref": "8:38", "q": "﴿قُل لِّلَّذِينَ كَفَرُوٓاْ إِن يَنتَهُواْ يُغۡفَرۡ لَهُم مَّا قَدۡ سَلَفَ﴾", "en": "Stopping wipes away the past", "ar": "الانتهاء يمحو ما سلف"}, {"ref": "47:4", "q": "﴿حَتَّىٰ تَضَعَ ٱلۡحَرۡبُ أَوۡزَارَهَاۚ﴾", "en": "Until the war lays down its burdens", "ar": "حتى تضع الحرب أوزارها"}, {"ref": "2:256", "q": "﴿لَآ إِكۡرَاهَ فِي ٱلدِّينِۖ قَد تَّبَيَّنَ ٱلرُّشۡدُ مِنَ ٱلۡغَيِّۚ﴾", "en": "And, later in this surah (2:256): no compulsion in religion", "ar": "وفي هذه السورة بعدُ (٢٥٦): لا إكراه في الدين"}], "v": 1, "p": 407, "pe": 408, "sid": 408},
  {"a": [194, 194], "h": "\"Transgress against him as he transgressed against you\" — why \"transgress\" is allowed but \"wrong\" never is", "hAr": "﴿فَٱعۡتَدُواْ عَلَيۡهِ بِمِثۡلِ مَا ٱعۡتَدَىٰ عَلَيۡكُمۡۚ﴾ — لماذا جاز «الاعتداء» ولم يَجُز «الظلم»", "said": "بين أن مراعاة حرمة الشهر واجبة لمن راعى حرمته، وأن من هتكها اقتص منه، وسبب نزول ذلك أن العرب فخرت بصرف النبي - عليه السلام - عام الحديبية عن البلد الحرام، وكان ذلك في ذي القعدة، فمكنه الله تعالى من دخوله في العام القابل في القعدة ... إن قيل: كيف رخص في الاعتداء وهو ظلم وقد منع منه آنفا بقوله: ﴿وَلَا تَعۡتَدُوٓاْۚ﴾، قيل: الاعتداء مجاوزة الحد، ومنه قيل: \" عدا فلان طوره \"، و \" لا تعد طورك \"، ثم استعير الاعتداء في الظلم من حيث أنه تجاوز الحد الذي حده العقل أو الشرع، والذي منع تجاوز ذلك ابتداء، فقد أباح لمن اعتدي عليه جزاء ... ثم للمجازاة أيضا حد لا يجوز أن يتجاوزه، وإياه عنى بقوله: ﴿فَمَنِ ٱعۡتَدَىٰ بَعۡدَ ذَٰلِكَ﴾ ... إن قيل: هل كان يجوز لو قيل: (من ظلمكم فاظلموهم)؟ قيل: لا يجوز ذلك، لأن الظلم إنما هو وضع الشيء في غير موضعه الذي يحق أن يوضع فيه، وهذا في كل حال مذموم", "en": "The sanctity of the sacred month is to be kept toward those who keep it; whoever violates it is answered in kind. The occasion: the Quraysh boasted of having turned the Prophet ﷺ back from Makkah in the year of al-Hudaybiyah, in the month of Dhu al-Qa'dah; Allah let him enter it the next year, in the same month.\nBut \"do not transgress\" was just said — how is \"transgress against him\" now allowed? Because i'tida' means crossing a limit, as in \"he overstepped his bounds\"; it is called injustice when it crosses the limit set by reason or law. What is forbidden is to START it; what is allowed is to repay one who started it. So there are two kinds: transgression that begins — injustice, forbidden; and transgression that repays — retaliation, which is justice. And repayment itself has a limit that may not be crossed: \"whoever transgresses after that…\".\nCould it have said \"whoever wrongs you, wrong him\"? Never. Zulm, wrong, is putting a thing where it does not belong, and that is blameworthy in every case; i'tida' is crossing a set line, which is not in itself blameworthy. The old Arab saying \"whoever wrongs you, wrong him\" was a lapse into their custom of licensed injustice, like the poet's \"let no one be ignorant against us, or we will be more ignorant than the ignorant\" — ignorance is blameworthy always, and no wise speaker commands it.\nAnd the verse shows that whoever destroys something of another's must make it good with its like — the same kind if it is measured, weighed or counted, otherwise its value.", "ar": "بيّن أن مراعاة حرمة الشهر واجبةٌ لمن راعى حرمته، وأن من هتكها اقتُصّ منه. وسبب نزولها أن العرب فخرت بصرف النبيّ ﷺ عام الحديبية عن البلد الحرام في ذي القعدة، فمكّنه الله من دخوله في العام القابل في ذي القعدة.\nفإن قيل: كيف رخّص في الاعتداء وقد منع منه آنفًا بقوله ﴿وَلَا تَعۡتَدُوٓاْۚ﴾؟ قيل: «الاعتداء» مجاوزة الحدّ — ومنه «عدا فلانٌ طوره» —، ثم استُعير للظلم لأنه تجاوزٌ للحدّ الذي حدّه العقل أو الشرع؛ فالممنوع الاعتداء ابتداءً — وهو ظلم —، والمباح لمن اعتُدي عليه الجزاء — وهو قصاصٌ وعدل —؛ وللمجازاة أيضًا حدٌّ لا يجوز تجاوزه: ﴿فَمَنِ ٱعۡتَدَىٰ بَعۡدَ ذَٰلِكَ﴾.\nولو قيل «من ظلمكم فاظلموهم» لم يجز: فالظلم وضع الشيء في غير موضعه، وهو مذمومٌ في كلّ حال؛ والاعتداء مجاوزة الحدّ المحدود، ولا يكون مذمومًا بإطلاق. وقول بعض العرب «من ظلمك فاظلمه» انحرافٌ وترخّصٌ في الظلم على عادتهم، كقول الشاعر: «ألا لا يجهلنْ أحدٌ علينا — فنجهلَ فوق جهل الجاهلينا»، والجهل مذمومٌ على كلّ حال، ولا يكاد يرد الأمر به من حكيم.\nوفي الآية دلالةٌ أن من استهلك لغيره شيئًا لزمه مثله: مثلُه في الجنس إن كان مكيلًا أو موزونًا أو معدودًا، وإلا فقيمته.", "links": [{"ref": "2:190", "q": "﴿وَلَا تَعۡتَدُوٓاْۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ﴾", "en": "The transgression that is forbidden: starting it", "ar": "الاعتداء الممنوع: الابتداء"}, {"ref": "16:126", "q": "﴿وَإِنۡ عَاقَبۡتُمۡ فَعَاقِبُواْ بِمِثۡلِ مَا عُوقِبۡتُم بِهِۦۖ وَلَئِن صَبَرۡتُمۡ لَهُوَ خَيۡرٞ لِّلصَّٰبِرِينَ﴾", "en": "Repayment in kind — and patience is better", "ar": "الجزاء بالمثل، والصبر خير"}, {"ref": "42:40", "q": "﴿وَجَزَٰٓؤُاْ سَيِّئَةٖ سَيِّئَةٞ مِّثۡلُهَاۖ فَمَنۡ عَفَا وَأَصۡلَحَ فَأَجۡرُهُۥ عَلَى ٱللَّهِۚ﴾", "en": "Its like — or pardon", "ar": "المثل أو العفو"}], "v": 1, "p": 408, "pe": 409, "sid": 409},
  {"a": [194, 194], "h": "\"They plotted, and Allah plotted\" — words that are praise or blame only by their aim", "hAr": "﴿وَمَكَرُواْ وَمَكَرَ ٱللَّهُۖ﴾ — ألفاظٌ تُمدح أو تُذمّ بمقصدها", "said": "فإن قيل: فقد قال الله: ﴿وَمَكَرُواْ وَمَكَرَ ٱللَّهُۖ﴾ قيل: حقيقة المكر إظهار أمر يعتقد فيه الناظر إليه الجاهل بحقيقته اعتقادا ... وكذلك الاحتيال والخديعة والسخرية ومن قصد بشيء من ذلك أمرا قبيحا، فهو مذموم وإن قصد به فعلا جميلا فهو محمود، فإذن يصح أن يمدح بذلك من يتحرى مقصدا حسنا، ولهذا قال بعض العلماء: إن الله - عز وجل - يخدعنا عن النار كما يخدع الصبي أبوه عن المضار ... وقوله: ﴿وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِينَ﴾، تنبيه أن توفيق الله يصحب المتقي", "en": "If \"wrong\" may never be commanded, what of \"they plotted, and Allah plotted\"? Ar-Raghib: makr, plotting, is showing something so that one who does not know its reality takes it for something else; stratagem, deception and mockery are of the same kind. When they are aimed at something ugly they are blameworthy; when aimed at something good they are praiseworthy — so they can be said in praise of one who aims at good. As a scholar put it: Allah \"tricks\" us away from the Fire, as a father tricks his little child away from harm.\n\"And know that Allah is with the God-fearing\": His help and enabling go with the one who is mindful of Him.", "ar": "فإن قيل: فقد قال الله ﴿وَمَكَرُواْ وَمَكَرَ ٱللَّهُۖ﴾؟ قيل: حقيقة المكر إظهار أمرٍ يعتقد فيه الناظر الجاهل بحقيقته غير ما هو؛ وكذلك الاحتيال والخديعة والسخرية: من قصد بشيءٍ منها أمرًا قبيحًا فهو مذموم، ومن قصد به فعلًا جميلًا فهو محمود؛ فيصحّ أن يُمدح بذلك من يتحرّى مقصدًا حسنًا. ولهذا قال بعض العلماء: «إن الله يخدعنا عن النار كما يخدع الصبيَّ أبوه عن المضارّ».\nو﴿وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِينَ﴾: تنبيهٌ أن توفيق الله يصحب المتّقي.", "links": [{"ref": "3:54", "q": "﴿وَمَكَرُواْ وَمَكَرَ ٱللَّهُۖ وَٱللَّهُ خَيۡرُ ٱلۡمَٰكِرِينَ﴾", "en": "Plotting — praised or blamed by its aim", "ar": "المكر — يُمدح أو يُذمّ بمقصده"}, {"ref": "4:142", "q": "﴿إِنَّ ٱلۡمُنَٰفِقِينَ يُخَٰدِعُونَ ٱللَّهَ وَهُوَ خَٰدِعُهُمۡ﴾", "en": "Deception turned back on the deceivers", "ar": "خداعٌ يرتدّ على أهله"}], "v": 1, "p": 409, "pe": 409, "sid": 410},
  {"a": [195, 195], "h": "\"Do not throw yourselves into ruin\" — the moth and the lamp; the jurist's view and the devoted one's", "hAr": "﴿وَلَا تُلۡقُواْ بِأَيۡدِيكُمۡ إِلَى ٱلتَّهۡلُكَةِ﴾ — الفراشة والسراج؛ نظر الفقيه ونظر المجاهد", "said": "وقيل معناه: ولا تلقوا أنفسكم بأيديكم إلى الهلاك، نحو قوله: ﴿وَلَا تَقۡتُلُوٓاْ أَنفُسَكُمۡۚ﴾، وذلك بالتعرض لما يستوخم عاقبته جهلا به، مثل الفراشة تأتي إذا رأت لهبا من السراج، فتلقي نفسها فيه، وتأولت الآية على وجهين بنظرين مختلفين .. أحدهما: أنه نهي عن الإسراف في الإنفاق، وعن التهور في الإقدام، والثاني: أنه نهي عن البخل بالمال، والقعود عن الجهاد، وكلا المعنيين يراد بها، فالإنسان كما أنه منهي عن الإسراف في [الإنفاق] والتهور في الإقدام، فهو منهي عن البخل وعن الإحجام في الجهاد ... ووجه ذلك أن الفقيه من حيث أنه يحكم بالظاهر على الكافة يراعي أحوالهم، والمجاهد من حيث أنه يوفر على مراعاة الحق عن مراعاة نفسه لا يرى الإلقاء بيده إلى التهلكة إلا الإخلال بترك وظائف الحق", "en": "Halak, ruin, is a thing reaching the end of its decay. \"Do not throw yourselves with your own hands into ruin\" — by rushing, out of ignorance, into what ends badly, like the moth that sees the lamp's flame and throws itself into it.\nThe verse has been read two ways, from two points of view, and both are meant: it forbids extravagance in spending and recklessness in going forward — and it forbids stinginess with wealth and holding back from striving in Allah's cause. A person is forbidden both extremes: \"those who, when they spend, are neither wasteful nor mean\"; \"do not chain your hand to your neck, nor stretch it out completely\".\nSome saw the verse through two lenses — the jurist's and the devoted striver's — and both are right in their way. The jurist judges by outward things for everyone, and so weighs people's circumstances. The one who has given himself to Allah's right rather than his own sees only one kind of \"ruin\": failing in what Allah is owed — \"Allah has bought from the believers their selves and their wealth, in return for Paradise\".\n\"And do good (ahsinu)\": ihsan is seeking justice and then going beyond it — \"Allah commands justice and excellence\" — and His love for those who do good shows how high their rank is.", "ar": "«الهلاك» انتهاء الشيء في الفساد. و﴿وَلَا تُلۡقُواْ بِأَيۡدِيكُمۡ إِلَى ٱلتَّهۡلُكَةِ﴾: لا تلقوا أنفسكم بأيديكم إلى الهلاك — كقوله ﴿وَلَا تَقۡتُلُوٓاْ أَنفُسَكُمۡۚ﴾ —، بالتعرّض لما تُستوخم عاقبته جهلًا به، كالفراشة ترى لهب السراج فتلقي نفسها فيه.\nوتُؤوّلت الآية على وجهين بنظرين مختلفين، وكلاهما مراد: نهيٌ عن الإسراف في الإنفاق والتهوّر في الإقدام، ونهيٌ عن البخل بالمال والقعود عن الجهاد؛ فالإنسان منهيٌّ عن الطرفين: ﴿وَٱلَّذِينَ إِذَآ أَنفَقُواْ لَمۡ يُسۡرِفُواْ وَلَمۡ يَقۡتُرُواْ﴾، ﴿وَلَا تَجۡعَلۡ يَدَكَ مَغۡلُولَةً إِلَىٰ عُنُقِكَ وَلَا تَبۡسُطۡهَا كُلَّ ٱلۡبَسۡطِ﴾.\nوقال بعضهم: يُنظر إليها بنظرين: نظر الفقيه ونظر المجاهد، وكلاهما صحيحٌ بوجه: فالفقيه يحكم بالظاهر على الكافّة فيراعي أحوالهم؛ والمجاهد الذي توفّر على مراعاة الحقّ دون مراعاة نفسه لا يرى الإلقاء إلى التهلكة إلا في الإخلال بوظائف الحقّ — وإلى هذه الحالة أشار: ﴿إِنَّ ٱللَّهَ ٱشۡتَرَىٰ مِنَ ٱلۡمُؤۡمِنِينَ أَنفُسَهُمۡ وَأَمۡوَٰلَهُم بِأَنَّ لَهُمُ ٱلۡجَنَّةَۚ﴾.\nو﴿وَأَحۡسِنُوٓاْۚ﴾: تحرّوا الإحسان — وهو تحرّي العدالة والزيادة عليها —: ﴿إِنَّ ٱللَّهَ يَأۡمُرُ بِٱلۡعَدۡلِ وَٱلۡإِحۡسَٰنِ﴾؛ ثم نبّه بمحبّته للمحسنين على شرف منزلتهم.", "links": [{"ref": "25:67", "q": "﴿وَٱلَّذِينَ إِذَآ أَنفَقُواْ لَمۡ يُسۡرِفُواْ وَلَمۡ يَقۡتُرُواْ وَكَانَ بَيۡنَ ذَٰلِكَ قَوَامٗا﴾", "en": "Neither extreme", "ar": "لا إفراط ولا تفريط"}, {"ref": "17:29", "q": "﴿وَلَا تَجۡعَلۡ يَدَكَ مَغۡلُولَةً إِلَىٰ عُنُقِكَ وَلَا تَبۡسُطۡهَا كُلَّ ٱلۡبَسۡطِ﴾", "en": "The hand neither chained nor wide open", "ar": "يدٌ لا مغلولة ولا مبسوطة كلّ البسط"}, {"ref": "9:111", "q": "﴿إِنَّ ٱللَّهَ ٱشۡتَرَىٰ مِنَ ٱلۡمُؤۡمِنِينَ أَنفُسَهُمۡ وَأَمۡوَٰلَهُم بِأَنَّ لَهُمُ ٱلۡجَنَّةَۚ﴾", "en": "The devoted one's view", "ar": "نظر المتجرّد لله"}, {"ref": "4:29", "q": "﴿وَلَا تَقۡتُلُوٓاْ أَنفُسَكُمۡۚ إِنَّ ٱللَّهَ كَانَ بِكُمۡ رَحِيمٗا﴾", "en": "Do not destroy yourselves", "ar": "لا تقتلوا أنفسكم"}], "v": 1, "p": 410, "pe": 411, "sid": 411},
  {"a": [196, 196], "h": "\"Complete the Hajj and the 'umrah for Allah\" — why \"for Allah\" is said here and not of prayer", "hAr": "﴿وَأَتِمُّواْ ٱلۡحَجَّ وَٱلۡعُمۡرَةَ لِلَّهِۚ﴾ — لماذا قيل «لله» هنا ولم يُقَل في الصلاة", "said": "وقيل إنه خطاب لهم ولمن لم يتلبس بالعبادة وذكر لفظ الإتمام تنبيه على توفية حقهما وإكمال شرائطهما، ولذلك قال أمير المؤمنين: \" من إتمامهما أن تحرم بهما من دويرة أهلك \" ... وإنما قال في الحج والعمرة \" لله \" ولم يقل ذلك في الصلاة والزكاة من أجل أنهم كانوا يتقربون ببعض أفعال الحج والعمرة إلى الأصنام، فخصهما بالذكر لله تعالى حثا على الإخلاص فيهما ومجانبة ذلك الاعتقاد المحظور", "en": "\"Complete them\": give both their full due and fulfil all their conditions — as 'Ali said, \"part of completing them is to enter ihram for them from your own doorstep\". (Abu Hanifah drew from it that any act of worship begun voluntarily must be completed; ash-Shafi'i, that the 'umrah is obligatory.)\nWhy \"for Allah\" with the Hajj and 'umrah, when it is not said with prayer or zakat? Because in the days of ignorance people offered some of the rites of Hajj and 'umrah to idols. So these two were marked out as \"for Allah\" — a call to sincerity in them, and to leave that forbidden belief behind.\nThe rest of the verse sets out the rulings for one who is prevented from finishing, and for one who is ill: the Prophet ﷺ told Ka'b ibn 'Ujrah at al-Hudaybiyah, whose head was troubled by lice, to shave it and then offer a sacrifice, or fast three days, or feed six needy people — the \"ransom of fasting, charity or sacrifice\".", "ar": "﴿وَأَتِمُّواْ ٱلۡحَجَّ وَٱلۡعُمۡرَةَ﴾: قيل خطابٌ لمن خرج حاجًّا أو معتمرًا ألّا ينصرف حتى يقضيهما — وبه احتجّ أبو حنيفة على وجوب إتمام كلّ عبادةٍ دخل فيها متنفّلًا —؛ وقيل: خطابٌ لهم ولمن لم يتلبّس بالعبادة، وذكر الإتمام تنبيهٌ على توفية حقّهما وإكمال شرائطهما، ولذلك قال عليٌّ: «من إتمامهما أن تُحرم بهما من دُوَيرة أهلك» — وبه احتجّ الشافعيّ على وجوب العمرة.\nوإنما قال في الحجّ والعمرة ﴿لِلَّهِۚ﴾ ولم يقله في الصلاة والزكاة، لأنهم كانوا يتقرّبون ببعض أفعال الحجّ والعمرة إلى الأصنام، فخصّهما بذكر الله حثًّا على الإخلاص فيهما ومجانبة ذلك الاعتقاد المحظور.\nوفي بقيّة الآية أحكام المُحصَر والمريض؛ وقد بيّن النبيّ ﷺ الفدية لكعب بن عُجرة يوم الحديبية وقد آذاه هوامّ رأسه: أن يحلق ويذبح نسيكة، أو يصوم ثلاثة أيام، أو يطعم ستّة مساكين.", "links": [{"ref": "98:5", "q": "﴿وَمَآ أُمِرُوٓاْ إِلَّا لِيَعۡبُدُواْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ﴾", "en": "Worship for Allah alone", "ar": "العبادة لله وحده"}, {"ref": "22:27", "q": "﴿وَأَذِّن فِي ٱلنَّاسِ بِٱلۡحَجِّ يَأۡتُوكَ رِجَالٗا وَعَلَىٰ كُلِّ ضَامِرٖ﴾", "en": "The call to the Hajj", "ar": "الأذان بالحجّ"}], "v": 1, "p": 412, "pe": 412, "sid": 413},
  {"a": [196, 196], "h": "\"That is ten complete\" — why the obvious is said: the Quran speaks plainly to all, and deeply to the learned", "hAr": "﴿تِلۡكَ عَشَرَةٞ كَامِلَةٞۗ﴾ — لماذا قيل الواضح: القرآن يخاطب العامّة بالبيان والخاصّة بالإيجاز", "said": "إن قيل: ما الحاجة إلى ذكر: \" تلك عشرة كاملة \" عقب قوله (سبعة، وثلاثة ... قيل: قد أجيب عن ذلك بأجوبة .. الأول: أنه لما قال: ﴿ثَلَٰثَةِ أَيَّامٖ فِي ٱلۡحَجِّ وَسَبۡعَةٍ إِذَا رَجَعۡتُمۡۗ﴾ كان يحتمل التخيير، وأن كل واحد منهما على الانفراد يقوم مقام الهدي فبين أن مجموعهما ... يقوم مقامه، والثاني: أنه لما قصد بيان كمال الحكم، وأن ذلك يحصل في صوم العشرة، ذكر لفظ العشرة تأكيدا ... وذاك أن الخطاب العامي، أعني ما يفهم به الخاص والعام الذين هم أهل الطبع لا أهل الارتياض بالتعلم لا يكون إلا تكريرات الكلام وزيادات البيان ليحسن إفهام الكافة، ولهذا جاء ... ما يتعلق حكمه بالكافة في غاية الظهور، وما هو مختص علمه بالراسخين في العلم جاء على ضرب من الإيجاز والغموض، إذ كانوا بمعرفتهم يمكنهم أن يتوصلوا إلى حقائقه، وما هو متردد بين العامة والخاصة كذكر التوحيد والنبوة ذكر تارة بلفظ مبسوط، ليظهر منه للعامة ما يقنعهم، وتارة بلفظ وجيز ليستخرج منه الخاصة ما يتضمنه", "en": "\"Three days during the Hajj and seven when you return — that is ten complete.\" Anyone can add three and seven — why say \"ten\", and why \"complete\"? Ar-Raghib gives several answers.\nFirst: \"three… and seven\" might have been taken as a choice — that either alone could replace the sacrifice; \"ten complete\" shows it is the two together.\nSecond, and deeper: speech meant for everyone — for people who understand by nature, not by long training — has to repeat and add clarity, so that all can grasp it. That is why in the Quran whatever concerns everyone's practice is set out with the utmost plainness; what belongs to those firmly grounded in knowledge comes in concise and subtle words, since their learning lets them reach its depths; and what lies between — like Allah's oneness and prophethood — comes sometimes at length, so that ordinary people find in it what convinces them, and sometimes briefly, so that the learned may draw out all it contains.", "ar": "فإن قيل: ما الحاجة إلى ﴿تِلۡكَ عَشَرَةٞ كَامِلَةٞۗ﴾ عقب «ثلاثةٍ وسبعة»، ولا يشكّ ذو أدنى بصيرةٍ أن الثلاثة والسبعة عشرة؟ قيل: أُجيب بأجوبة:\nالأوّل: لمّا قال ﴿فَصِيَامُ ثَلَٰثَةِ أَيَّامٖ فِي ٱلۡحَجِّ وَسَبۡعَةٍ إِذَا رَجَعۡتُمۡۗ﴾ احتمل التخيير، وأن كلّ واحدٍ منهما منفردًا يقوم مقام الهدي، فبيّن أن مجموعهما هو الذي يقوم مقامه.\nوالثاني: لمّا قصد بيان كمال الحكم ذكر العشرة تأكيدًا؛ فالخطاب العامّيّ — الذي يفهمه الخاصّ والعامّ من أهل الطبع لا أهل الارتياض بالتعلّم — لا يكون إلا بتكرير الكلام وزيادة البيان ليحسن إفهام الكافّة. ولهذا جاء في القرآن ما يتعلّق حكمه بالكافّة في غاية الظهور، وما يختصّ علمه بالراسخين في العلم على ضربٍ من الإيجاز والغموض، إذ يمكنهم بمعرفتهم أن يتوصّلوا إلى حقائقه؛ وما هو متردّدٌ بين العامّة والخاصّة — كذكر التوحيد والنبوّة — ذُكر تارةً بلفظٍ مبسوط ليظهر منه للعامّة ما يقنعهم، وتارةً بلفظٍ وجيزٍ ليستخرج منه الخاصّة ما يتضمّنه.", "links": [{"ref": "3:7", "q": "﴿هُوَ ٱلَّذِيٓ أَنزَلَ عَلَيۡكَ ٱلۡكِتَٰبَ مِنۡهُ ءَايَٰتٞ مُّحۡكَمَٰتٌ هُنَّ أُمُّ ٱلۡكِتَٰبِ وَأُخَرُ مُتَشَٰبِهَٰتٞۖ﴾", "en": "The plain and the deep", "ar": "المحكم والمتشابه"}, {"ref": "4:83", "q": "﴿وَلَوۡ رَدُّوهُ إِلَى ٱلرَّسُولِ وَإِلَىٰٓ أُوْلِي ٱلۡأَمۡرِ مِنۡهُمۡ لَعَلِمَهُ ٱلَّذِينَ يَسۡتَنۢبِطُونَهُۥ مِنۡهُمۡۗ﴾", "en": "What the learned draw out", "ar": "ما يستنبطه أهل العلم"}, {"ref": "54:17", "q": "﴿وَلَقَدۡ يَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرٖ﴾", "en": "Made easy for all", "ar": "ميسَّرٌ للذكر"}], "v": 1, "p": 414, "pe": 415, "sid": 415},
  {"a": [196, 196], "h": "Why ten is \"complete\" — ar-Raghib's aside on the science of number", "hAr": "لماذا العشرة «كاملة» — استطراد الراغب في علم العدد", "said": "والثالث: أن قوله: ﴿تِلۡكَ عَشَرَةٞ كَامِلَةٞۗ﴾ استطراد كلام، وتنبيه على فضيلة علم العدد، وذاك أنه قد قيل: العدد أول العلوم وأشرفها، أما كونه أولا، فلأن ما عداه به تميز وتفضل، وأما كونه أشرف، فلأنه لا اختلاف فيه ولا تغيير، بل هو لازم طريقة واحدة، فذكر العشرة، ووصفها بالكاملة، إذ هي عدد كمل فيه خواص الأعداد فإن الواحد مبدأ العدد، والاثنين أول العدد، والثلاثة أول عدد فرد، والأربعة أول عدد زوج ... أي مجتمع من ضرب عدد في نفسه، والخمسة أول عدد دائر، والستة أول عدد تام، أي إذا أخذت أجزاؤه لم يزد عليه ولم ينقص منه، والسبعة أول عدد أول ... والثمانية أول عدد زوج الزوج والتسعة أول عدد مثلث، والعشرة أول عقد ينتهي إليه العدد، فإن كل عدد بعده مكرر منه بما قبله، فإذن العشرة هي العدد الكامل", "en": "His third answer is a scholar's delight: \"ten complete\" is also a nod to the science of number. It has been said that number is the first of the sciences and the noblest — first, because everything else is distinguished and ranked by it; noblest, because in it there is no disagreement and no change: it keeps one path.\nAnd ten is \"complete\", he says, because in it the properties of numbers are all gathered, each number up to nine having its own \"first\" in the arithmetic of his day — three the first odd number, four the first square (a number multiplied by itself), six the first \"perfect\" number (its parts add up to exactly itself: 1 + 2 + 3), and so on — and ten is the first \"knot\" at which counting arrives: every number after it repeats what came before. So ten is the complete number.", "ar": "والجواب الثالث: أن ﴿تِلۡكَ عَشَرَةٞ كَامِلَةٞۗ﴾ استطرادٌ وتنبيهٌ على فضيلة علم العدد؛ فقد قيل: العدد أوّل العلوم وأشرفها: أوّلها لأن ما عداه به يتميّز ويتفاضل، وأشرفها لأنه لا اختلاف فيه ولا تغيّر، بل يلزم طريقةً واحدة.\nووصف العشرة بالكاملة لأنها عددٌ كملت فيه خواصّ الأعداد، لكلّ عددٍ من الواحد إلى التسعة «أوّليّةٌ» في علم العدد عندهم — فالثلاثة أوّل عددٍ فرد، والأربعة أوّل عددٍ مجذور (مجتمعٌ من ضرب عددٍ في نفسه)، والستّة أوّل عددٍ تامّ (إذا جُمعت أجزاؤه ساوته: ١ + ٢ + ٣)، وهكذا —، والعشرة أوّل عقدٍ ينتهي إليه العدد، فكلّ عددٍ بعده مكرَّرٌ ممّا قبله؛ فالعشرة هي العدد الكامل.", "links": [{"ref": "72:28", "q": "﴿وَأَحۡصَىٰ كُلَّ شَيۡءٍ عَدَدَۢا﴾", "en": "All things counted", "ar": "كلّ شيءٍ محصًى عددًا"}, {"ref": "10:5", "q": "﴿لِتَعۡلَمُواْ عَدَدَ ٱلسِّنِينَ وَٱلۡحِسَابَۚ﴾", "en": "Number and reckoning", "ar": "العدد والحساب"}], "v": 1, "p": 415, "pe": 415, "sid": 416},
  {"a": [197, 197], "h": "\"No obscenity, no wickedness, no quarrelling in the Hajj\" — what each pillar of Islam is for", "hAr": "﴿فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِي ٱلۡحَجِّۗ﴾ — ما جُعل له كلّ ركن", "said": "إن قيل: الفسوق محظور في كل حال، فكيف خص به الحج؟ ... قيل: تخصيص الحج به تنبيه على شرفه وعظم موقعه، كقوله: ﴿فَلَا تَظۡلِمُواْ فِيهِنَّ أَنفُسَكُمۡۚ﴾ وإن كان ظلم النفس في كل حال مكروها ... وقيل قوله: ﴿فَلَا رَفَثَ وَلَا فُسُوقَ﴾ إشارة إلى أن من التزم هذا الفرض وتحراه يمنعه عن الرفث والفسوق، وكأنه نبه على علة ما أوجب لأجله الحج، فهو تهذيب اللسان عن الخنا، وإصلاح البدن [بالمنع] من تعاطي الفسق، كما جعل الصلاة علة لترك الفحشاء والمنكر، والصوم علة للتقوى في قوله: ﴿لَعَلَّكُمۡ تَتَّقُونَ﴾، والزكاة علة لتزكية النفس في قوله: ﴿وَتُزَكِّيهِم بِهَا﴾", "en": "Wickedness is forbidden at all times — why name the Hajj? Some say it means the things forbidden only in the state of ihram (hunting, perfume, sewn clothing). Others: naming the Hajj shows how noble and weighty it is — as \"do not wrong yourselves in them [the sacred months]\" does not mean wronging oneself is fine at other times; and as the Prophet ﷺ said, \"when one of you is fasting, let him not behave coarsely or foolishly\". \"No quarrelling\": no wrangling — or no more doubt about when the Hajj falls; or a call to affection and leaving whatever breeds hatred. All may be meant.\nAnd one reading sees in these words the very purpose of the Hajj: whoever truly takes it on, it holds him back from obscenity and wickedness — it refines the tongue from foulness and corrects the body by keeping it from sin. Just so, Allah named the purpose of each pillar: prayer \"restrains from indecency and wrong\"; fasting \"so that you may become God-conscious\"; zakat \"to purify them by it\".", "ar": "فإن قيل: الفسوق محظورٌ في كلّ حال، فلمَ خُصّ به الحجّ؟ قيل: الفسوق هنا ما يُحظر في حال الحجّ خاصّةً كالصيد والطيب واللباس؛ أو تخصيص الحجّ به تنبيهٌ على شرفه وعظم موقعه، كقوله ﴿فَلَا تَظۡلِمُواْ فِيهِنَّ أَنفُسَكُمۡۚ﴾ وظلم النفس مكروهٌ في كلّ حال، وكقوله ﷺ: «إذا كان صوم أحدكم فلا يرفث ولا يجهل». و﴿وَلَا جِدَالَ﴾: لا مماراة؛ وقيل: لا شكّ في أن وقته مقرّرٌ في ذي الحجّة؛ وقيل: حثٌّ على التحابّ وترك ما يؤدّي إلى التباغض — وكلّ ذلك يصحّ إرادته.\nوقيل: في ﴿فَلَا رَفَثَ وَلَا فُسُوقَ﴾ إشارةٌ إلى أن من التزم هذا الفرض وتحرّاه منعه من الرفث والفسوق، فكأنه نبّه على علّة إيجاب الحجّ: تهذيب اللسان عن الخنا، وإصلاح البدن بالمنع من الفسق — كما جعل الصلاة علّةً لترك الفحشاء والمنكر، والصوم علّةً للتقوى ﴿لَعَلَّكُمۡ تَتَّقُونَ﴾، والزكاة علّةً لتزكية النفس ﴿وَتُزَكِّيهِم بِهَا﴾.", "links": [{"ref": "29:45", "q": "﴿إِنَّ ٱلصَّلَوٰةَ تَنۡهَىٰ عَنِ ٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِۗ﴾", "en": "Prayer: restraint from indecency", "ar": "الصلاة: النهي عن الفحشاء"}, {"ref": "2:183", "q": "﴿كُتِبَ عَلَيۡكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ﴾", "en": "Fasting: God-consciousness", "ar": "الصوم: التقوى"}, {"ref": "9:103", "q": "﴿خُذۡ مِنۡ أَمۡوَٰلِهِمۡ صَدَقَةٗ تُطَهِّرُهُمۡ وَتُزَكِّيهِم بِهَا﴾", "en": "Zakat: purifying the soul", "ar": "الزكاة: تزكية النفس"}], "v": 1, "p": 417, "pe": 418, "sid": 418},
  {"a": [197, 197], "h": "\"Take provision — the best provision is God-consciousness\" — and its three levels", "hAr": "﴿وَتَزَوَّدُواْ فَإِنَّ خَيۡرَ ٱلزَّادِ ٱلتَّقۡوَىٰۖ﴾ — ومنازل التقوى الثلاث", "said": "وقوله: ﴿وَتَزَوَّدُواْ فَإِنَّ خَيۡرَ ٱلزَّادِ ٱلتَّقۡوَىٰۖ﴾ حث على تقوى الله واقتناء الأعمال الصالحة، والإعراض عن الدنيا سوى ما يتوصل به إلى الآخرة ... وقال أبو المطيع البلخي لحاتم الأصم: \" بلغني أنك تجوب البادية بلا زاد فقال: إنما أجوبها بأربعة أشياء، أرى الدنيا بحذافيرها ملكا لله، وأرى الخلق كلهم عبيدا لله، وأرى الأشياء كلها بيده، وأرى قضاءه نافذا في كل أرض \"، فقال: \" نعم الزاد زادك يا حاتم ... وقيل: تقواه حفظ النفس أن ينالها عقابه أو يتخطاها ثوابه، وذلك منعها متابعة الهوى، وحملها على طريق الهدى، وذلك على ثلاثة منازل ... الأول: ترك الكفر والكبائر، والثاني: ترك المحارم وأداء الفرائض اللذين يقتضيهما التزام الشرائع، والثالث: حفظ القلوب عن التلفت إلى الذنوب، وهو المعني، بقول من قال: \" التقوى هي التبرؤ من كل شيء سوى الله تعالى، ولا يحصل الثالث إلا بحصول الثاني، ولا الثاني إلا بحصول الأول \"، وعنى هاهنا الغاية، ولهذا خص أولو الألباب بالخطاب، فاللب أشرف أوصاف العقل", "en": "\"Take provision\" urges God-consciousness, gathering good deeds, and turning from the world except for what carries one to the next. (It is also said that people used to set out for the Hajj with no provisions and beg on the way; they were told to take provision — begging can itself go against God-consciousness.)\nAbu al-Muti' al-Balkhi said to Hatim al-Asamm, \"I hear you cross the desert with no provisions.\" Hatim replied: \"I cross it with four things: I see the whole world as Allah's property; I see all creatures as Allah's servants; I see all things in His hand; and I see His decree in force in every land.\" \"What fine provision you have, Hatim!\"\nGod-consciousness is guarding the soul from His punishment and from missing His reward — keeping it from following desire and holding it to the road of guidance. It has three levels: leaving disbelief and the major sins; leaving what is forbidden and doing what is obligatory; and guarding the heart from even turning toward sin — what was meant by \"God-consciousness is freeing yourself from everything but Allah\". The third comes only through the second, and the second only through the first. Here the highest level is meant — which is why it addresses \"people of understanding\": lubb is the kernel of reason, as a kernel is to its shell.", "ar": "﴿وَتَزَوَّدُواْ فَإِنَّ خَيۡرَ ٱلزَّادِ ٱلتَّقۡوَىٰۖ﴾: حثٌّ على تقوى الله واقتناء الأعمال الصالحة، والإعراض عن الدنيا إلا ما يُتوصَّل به إلى الآخرة. (وقيل: نزلت في قومٍ يحجّون بلا زادٍ ويتكفّفون الناس، والتكفّف قد ينافي التقوى.)\nوقال أبو المطيع البلخيّ لحاتم الأصمّ: بلغني أنك تجوب البادية بلا زاد! فقال: إنما أجوبها بأربعة أشياء: أرى الدنيا بحذافيرها ملكًا لله، وأرى الخلق كلّهم عبيدًا لله، وأرى الأشياء كلّها بيده، وأرى قضاءه نافذًا في كلّ أرض. فقال: نِعم الزاد زادك يا حاتم!\nو﴿وَٱتَّقُونِ يَٰٓأُوْلِي ٱلۡأَلۡبَٰبِ﴾: التقوى حفظ النفس أن ينالها عقابه أو يتخطّاها ثوابه، بمنعها متابعة الهوى وحملها على طريق الهدى؛ وهي ثلاث منازل: ترك الكفر والكبائر؛ ثم ترك المحارم وأداء الفرائض اللذين يقتضيهما التزام الشرائع؛ ثم حفظ القلوب عن التلفّت إلى الذنوب — وهو المعنيّ بقول من قال: «التقوى التبرّؤ من كلّ شيءٍ سوى الله» —؛ ولا يحصل الثالث إلا بالثاني، ولا الثاني إلا بالأوّل. والمراد هنا الغاية، ولهذا خُصّ أولو الألباب بالخطاب: فاللبّ أشرف أوصاف العقل، وهو منه كلبّ الشيء من قشره.", "links": [{"ref": "7:26", "q": "﴿وَلِبَاسُ ٱلتَّقۡوَىٰ ذَٰلِكَ خَيۡرٞۚ﴾", "en": "The garment of God-consciousness", "ar": "لباس التقوى"}, {"ref": "13:19", "q": "﴿إِنَّمَا يَتَذَكَّرُ أُوْلُواْ ٱلۡأَلۡبَٰبِ﴾", "en": "People of understanding", "ar": "أولو الألباب"}, {"ref": "11:6", "q": "﴿وَمَا مِن دَآبَّةٖ فِي ٱلۡأَرۡضِ إِلَّا عَلَى ٱللَّهِ رِزۡقُهَا﴾", "en": "Hatim's provision: trust in the Provider", "ar": "زاد حاتم: الثقة بالرازق"}], "v": 1, "p": 418, "pe": 419, "sid": 419},
  {"a": [198, 198], "h": "\"No blame in seeking bounty from your Lord\" — trade in the Hajj; and why stand at al-Mash'ar", "hAr": "﴿لَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَبۡتَغُواْ فَضۡلٗا مِّن رَّبِّكُمۡۚ﴾ — التجارة في الحجّ؛ ولماذا الوقوف بالمشعر", "said": "وكانت العرب تتحاشى من التجارة في الحج حتى إنهم كانوا يتجنبون المبايعة إذا دخل العشر الأواخر، وحتى سموا من يوالي متجرا في الحج: الداج دون الحاج، فأباح الله ذلك ... وقيل لبعض العلماء: \" لم أمر الناس بالمقام عند المشعر الحرام، وبالذكر؟، فقال: لأن الكعبة بيت الله [و]الحرم حجابه، والمشعر بابه، والوافد إذا قصد الباب أقام وتضرع، فإذا وصل إلى الحجاب، قدم قربانات، وقضى التفث، وتطهر، ثم يؤذن له في الدخول", "en": "The Arabs used to shy away from trade during the Hajj — they would stop buying and selling once the last ten days began, and called a man who traded then \"a hanger-on\", not \"a pilgrim\". Allah made it lawful: \"that they may witness benefits for themselves\"; \"others travel the land seeking Allah's bounty\".\n\"Remember Allah at al-Mash'ar al-Haram\" — at Muzdalifah; some say it means the combined sunset and night prayers there, prayer being called \"remembrance\". A scholar was asked why the pilgrims are made to stop at al-Mash'ar and remember Allah. He said: the Ka'bah is Allah's House, the Sanctuary is its veil, and al-Mash'ar is its gate. A visitor who reaches the gate waits there and pleads; when he reaches the veil, he offers his sacrifices, completes his cleansing and purifies himself — and then he is admitted.\n\"Remember Him as He has guided you\": let your remembrance be born of His guidance — \"though before it you were astray\", that is, unaware of the true knowledge, as in \"He found you unaware and guided you\".", "ar": "كانت العرب تتحاشى التجارة في الحجّ، حتى كانوا يتجنّبون المبايعة إذا دخل العشر، وسمّوا من يتّجر في الحجّ «الدّاجّ» لا «الحاجّ»؛ فأباح الله ذلك: ﴿لِّيَشۡهَدُواْ مَنَٰفِعَ لَهُمۡ﴾، ﴿وَءَاخَرُونَ يَضۡرِبُونَ فِي ٱلۡأَرۡضِ يَبۡتَغُونَ مِن فَضۡلِ ٱللَّهِ﴾.\nو﴿فَٱذۡكُرُواْ ٱللَّهَ عِندَ ٱلۡمَشۡعَرِ ٱلۡحَرَامِۖ﴾ — المزدلفة؛ وقيل: الجمع بين المغرب والعشاء فيها، والصلاة تُسمّى ذكرًا. وقيل لبعض العلماء: لمَ أُمر الناس بالمقام عند المشعر الحرام وبالذكر؟ فقال: لأن الكعبة بيت الله، والحرم حجابه، والمشعر بابه؛ والوافد إذا قصد الباب أقام وتضرّع، فإذا وصل إلى الحجاب قدّم قرباناتٍ وقضى تفثه وتطهّر، ثم يُؤذن له في الدخول.\nو﴿وَٱذۡكُرُوهُ كَمَا هَدَىٰكُمۡ﴾: ليكن ذكركم وليد هدايته لكم؛ ﴿وَإِن كُنتُم مِّن قَبۡلِهِۦ لَمِنَ ٱلضَّآلِّينَ﴾ — الضلال هنا الجهل بالمعارف الحقيقيّة، كقوله ﴿وَوَجَدَكَ ضَآلّٗا فَهَدَىٰ﴾.", "links": [{"ref": "22:28", "q": "﴿لِّيَشۡهَدُواْ مَنَٰفِعَ لَهُمۡ وَيَذۡكُرُواْ ٱسۡمَ ٱللَّهِ فِيٓ أَيَّامٖ مَّعۡلُومَٰتٍ﴾", "en": "Benefits — and remembrance", "ar": "منافع وذكر"}, {"ref": "73:20", "q": "﴿وَءَاخَرُونَ يَضۡرِبُونَ فِي ٱلۡأَرۡضِ يَبۡتَغُونَ مِن فَضۡلِ ٱللَّهِ﴾", "en": "Seeking Allah's bounty", "ar": "ابتغاء فضل الله"}, {"ref": "93:7", "q": "﴿وَوَجَدَكَ ضَآلّٗا فَهَدَىٰ﴾", "en": "\"Astray\" — unaware, then guided", "ar": "الضلال: عدم العلم ثم الهداية"}], "v": 1, "p": 419, "pe": 420, "sid": 420},
  {"a": [199, 199], "h": "\"Depart from where the people depart\" — no privileged class in the Hajj", "hAr": "﴿ثُمَّ أَفِيضُواْ مِنۡ حَيۡثُ أَفَاضَ ٱلنَّاسُ﴾ — لا طبقة مميّزة في الحجّ", "said": "روي أن قريشا لم يكونوا يقفون مع الناس بعرفة ولا يبيتون بالمزدلفة ويقولون: \" نحن أهل حرم الله \"، وكانوا يقفون دون عرفة فأمرهم الله تعالى أن يفيضوا مع سائر الناس، قاله ابن عباس، وعائشة، ومجاهد، والحسن ... والاستغفار، والتوبة، والإنابة، والأوبة تتقارب، لكن الاستغفار [طلب] غفر الذنب، والتوبة تركه، والإنابة: الرجوع عن الضلال إلى الهدى، والأوبة رجوع القلب إلى الله تعالى، وهذه المعاني وإن كانت متلازمة، فألفاظها اختلفت لاختلاف النظرات ... وبين أن الله تعالى غفور للمطيعين، رحيم بالعاصين، يدعوهم برحمته إلى بابه، ويرغبهم في جزيل ثوابه", "en": "The Quraysh used not to stand with everyone else at 'Arafah or spend the night at Muzdalifah; \"we are the people of Allah's Sanctuary\", they said, and stopped short of 'Arafah. Allah commanded them to depart together with all the people — so said Ibn 'Abbas, 'A'ishah, Mujahid and al-Hasan. In the Hajj no tribe stands above the rest.\nAnother reading: \"the people\" is Ibrahim — \"people\" used as praise, for one who has the full form of humanity, as one says \"now that is a man\"; and one person may be called by the name of a whole group when he stands in their place — \"Ibrahim was a nation\".\nFour words for coming back to Allah, close in meaning but seen from different sides: istighfar is asking that the sin be covered; tawbah is leaving it; inabah is turning from error to guidance; awbah is the heart's return to Allah. \"Allah is Forgiving\" to those who obey, \"Merciful\" to those who disobey — calling them by His mercy to His door, and drawing them with His great reward.", "ar": "رُوي أن قريشًا لم يكونوا يقفون مع الناس بعرفة ولا يبيتون بالمزدلفة، ويقولون: «نحن أهل حرم الله»، فكانوا يقفون دون عرفة؛ فأمرهم الله أن يُفيضوا مع سائر الناس — قاله ابن عباس وعائشة ومجاهد والحسن. فلا طبقة مميَّزة في الحجّ.\nوقيل: ﴿ٱلنَّاسُ﴾ هنا إبراهيم؛ فـ«الناس» يُستعمل للنوع، ويُستعمل مدحًا لمن وُجد فيه تمام الصورة المختصّة بالإنسانيّة — كقولهم «فلانٌ رجل» —؛ وقد يُسمّى الواحد باسم الجماعة لقيامه مقامهم: ﴿إِنَّ إِبۡرَٰهِيمَ كَانَ أُمَّةٗ﴾.\nو«الاستغفار» و«التوبة» و«الإنابة» و«الأوبة» متقاربة: فالاستغفار طلب غفر الذنب، والتوبة تركه، والإنابة الرجوع عن الضلال إلى الهدى، والأوبة رجوع القلب إلى الله؛ والمعاني متلازمة، واختلفت الألفاظ لاختلاف النظرات. و﴿إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ﴾: غفورٌ للمطيعين، رحيمٌ بالعاصين، يدعوهم برحمته إلى بابه ويرغّبهم في جزيل ثوابه.", "links": [{"ref": "49:13", "q": "﴿يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّا خَلَقۡنَٰكُم مِّن ذَكَرٖ وَأُنثَىٰ وَجَعَلۡنَٰكُمۡ شُعُوبٗا وَقَبَآئِلَ لِتَعَارَفُوٓاْۚ﴾", "en": "No tribe above another", "ar": "لا قبيلة فوق أخرى"}, {"ref": "16:120", "q": "﴿إِنَّ إِبۡرَٰهِيمَ كَانَ أُمَّةٗ قَانِتٗا لِّلَّهِ﴾", "en": "One man called \"a nation\"", "ar": "رجلٌ سُمّي أمّة"}, {"ref": "24:31", "q": "﴿وَتُوبُوٓاْ إِلَى ٱللَّهِ جَمِيعًا أَيُّهَ ٱلۡمُؤۡمِنُونَ لَعَلَّكُمۡ تُفۡلِحُونَ﴾", "en": "Returning to Allah together", "ar": "التوبة إلى الله جميعًا"}], "v": 1, "p": 421, "pe": 422, "sid": 422},
  {"a": [200, 200], "h": "\"Remember Allah as you remember your fathers — or more\" — pride in ancestry ended", "hAr": "﴿فَٱذۡكُرُواْ ٱللَّهَ كَذِكۡرِكُمۡ ءَابَآءَكُمۡ أَوۡ أَشَدَّ ذِكۡرٗاۗ﴾ — إبطال الفخر بالأنساب", "said": "وقولهم: إذا فعلت كذا فافعل كذا، يقال على ثلاثة أوجه: الأول: أن يكون \" افعل \" أمرا بما تقدم فعله نحو، ﴿إِذَا قُمۡتُمۡ إِلَى ٱلصَّلَوٰةِ فَٱغۡسِلُواْ﴾ الثاني: أن يكون الأمر بشيء هو من أبعاض ذلك الفعل وفي أثنائه، نحو: \" إذا صليت فاركع واسجد \"، والثالث: أن يكون بعده، نحو: ﴿فَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُواْ﴾ والآية، محمولة على ذلك [كله] تنبيها ففي ابتداء النسك ذكر، وهو التلبية وفي أثنائه ذكر، وهو عند المشعر والطواف، وفي انتهائه ذكر، وهو شكر الله- عز وجل- وذكره عند طواف الوداع ... ولما كان الإنسان لا يتشكك في أن أباه أحد أسباب وجوده، وأنه منه أوجد ولا ينسى ذكره في شيء من أحواله، وكانوا يتبجحون بمكانه، ويفتخرون بكونهم عنه، أمروا أن يذكروا الله كذكرهم آباءهم وأن يتحققوا أنه تعالى سبب وجودهم، بل سبب وجود آبائهم، وأن يفتخروا به كافتخارهم بآبائهم", "en": "\"When you have completed your rites, remember Allah\" — in Arabic, \"when you do X, do Y\" can mean before it (\"when you rise for prayer, wash\"), during it (\"when you pray, bow and prostrate\"), or after it (\"when the prayer is over, disperse\"). Here all three fit: remembrance at the start of the rites (the talbiyah), in the middle (at al-Mash'ar and in the tawaf), and at the end (thanks to Allah, and the farewell tawaf).\nA person never doubts that his father is one of the causes of his existence, and never forgets him; and the Arabs used to boast of their fathers — after the Hajj they would gather and recite their ancestors' glories. So they were told: remember Allah as you remember your fathers — know that He is the cause of your existence, and of your fathers' too, and take your pride in Him. The Prophet ﷺ said: \"Allah has removed from you the arrogance of the days of ignorance and its pride in forefathers. People are from Adam, and Adam is from dust\" — and recited: \"the noblest of you with Allah is the most God-conscious\".\n\"Or more\": \"or\" seems to offer a choice, but it demands more — thanks are owed in proportion to the favour, and Allah's favour is far greater than a father's.", "ar": "قولهم «إذا فعلتَ كذا فافعل كذا» على ثلاثة أوجه: أمرٌ بما يتقدّم الفعل — ﴿إِذَا قُمۡتُمۡ إِلَى ٱلصَّلَوٰةِ فَٱغۡسِلُواْ﴾ —، وأمرٌ بما هو من أبعاضه وفي أثنائه — «إذا صلّيت فاركع واسجد» —، وأمرٌ بما بعده — ﴿فَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُواْ﴾. والآية محمولةٌ على ذلك كلّه: ففي ابتداء النسك ذكرٌ — التلبية —، وفي أثنائه ذكرٌ — عند المشعر والطواف —، وفي انتهائه ذكرٌ — شكر الله وذكره عند طواف الوداع.\nولمّا كان الإنسان لا يشكّ أن أباه أحد أسباب وجوده ولا ينسى ذكره، وكانوا يتبجّحون بآبائهم ويفتخرون بهم بعد فراغهم من الحجّ، أُمروا أن يذكروا الله كذكرهم آباءهم، وأن يتحقّقوا أنه سبب وجودهم بل سبب وجود آبائهم، وأن يفتخروا به كافتخارهم بآبائهم. وعليه نبّه ﷺ: «إن الله أذهب عنكم نخوة الجاهليّة وتعظّمها بالآباء؛ الناس من آدم وآدم من تراب»، ثم تلا: ﴿إِنَّ أَكۡرَمَكُمۡ عِندَ ٱللَّهِ أَتۡقَىٰكُمۡۚ﴾.\nو﴿أَوۡ أَشَدَّ ذِكۡرٗاۗ﴾: «أو» وإن كانت للتخيير فمقتضى الكلام إيجاب أن يكون ذكره أشدّ، لأن شكر المنعم بقدر عظم نعمته، ونعمة الله أعظم من نعمة الأب.", "links": [{"ref": "49:13", "q": "﴿يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّا خَلَقۡنَٰكُم مِّن ذَكَرٖ وَأُنثَىٰ وَجَعَلۡنَٰكُمۡ شُعُوبٗا وَقَبَآئِلَ لِتَعَارَفُوٓاْۚ إِنَّ أَكۡرَمَكُمۡ عِندَ ٱللَّهِ أَتۡقَىٰكُمۡۚ﴾", "en": "Nobility is God-consciousness, not lineage", "ar": "الكرامة بالتقوى لا بالنسب"}, {"ref": "62:10", "q": "﴿فَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُواْ فِي ٱلۡأَرۡضِ﴾", "en": "\"When… then\" — after the act", "ar": "«إذا… فـ» — بعد الفعل"}, {"ref": "23:101", "q": "﴿فَلَآ أَنسَابَ بَيۡنَهُمۡ يَوۡمَئِذٖ وَلَا يَتَسَآءَلُونَ﴾", "en": "Lineage counts for nothing then", "ar": "لا أنساب يومئذ"}], "v": 1, "p": 423, "pe": 423, "sid": 424},
  {"a": [200, 200], "h": "\"Some say: Our Lord, give us in this world\" — why they asked for nothing else", "hAr": "﴿فَمِنَ ٱلنَّاسِ مَن يَقُولُ رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا﴾ — لماذا لم يسألوا غيرها", "said": "وإنما سألوه الدنيا دون الآخرة، لأنهم عرفوها ولم يعرفوا الآخرة، وكيف يسأل الآخرة من لا يعرفها؟، وكيف يعرفها من لم يتحقق كونها؟، وكيف يتحقق كونها من لم يبصرها؟ أي لم تدركها بصيرته؟ وليس يعني بقوله: (يقول) التفوه بذلك فقط، بل صرف العناية إليها والاهتمام بها", "en": "It is reported that they would pray, \"O Allah, increase our wealth and our children, send us rain, make our pastures grow\" — and ask nothing about their return to Him. They asked only for this world because it was the only one they knew. How can someone ask for the next world who does not know it? How can he know it if he has not become certain of it? And how can he be certain of it if he has not seen it — that is, if his inner sight has not grasped it? And \"says\" is not just words: it means pouring one's care and concern into it.", "ar": "رُوي أنهم كانوا يقولون: «اللهم أكثِر أموالنا وأولادنا، وأنزل علينا الغيث، وأنبت مرعانا»، ولا يسألون شيئًا من أمر آخرتهم. وإنما سألوه الدنيا دون الآخرة لأنهم عرفوها ولم يعرفوا الآخرة: وكيف يسأل الآخرة من لا يعرفها؟ وكيف يعرفها من لم يتحقّق كونها؟ وكيف يتحقّق كونها من لم يبصرها — أي لم تدركها بصيرته؟ وليس المراد بـ﴿يَقُولُ﴾ التفوّه فقط، بل صرف العناية إليها والاهتمام بها.", "links": [{"ref": "30:7", "q": "﴿يَعۡلَمُونَ ظَٰهِرٗا مِّنَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَهُمۡ عَنِ ٱلۡأٓخِرَةِ هُمۡ غَٰفِلُونَ﴾", "en": "Knowing only the surface of this world", "ar": "يعلمون ظاهرًا من الحياة الدنيا"}, {"ref": "17:18", "q": "﴿مَّن كَانَ يُرِيدُ ٱلۡعَاجِلَةَ عَجَّلۡنَا لَهُۥ فِيهَا مَا نَشَآءُ لِمَن نُّرِيدُ﴾", "en": "Wanting only the immediate", "ar": "من يريد العاجلة"}], "v": 1, "p": 424, "pe": 424, "sid": 425},
  {"a": [201, 201], "h": "\"Give us good in this world and good in the next\" — how a believer asks for the world", "hAr": "﴿رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا حَسَنَةٗ وَفِي ٱلۡأٓخِرَةِ حَسَنَةٗ﴾ — كيف يطلب المؤمن الدنيا", "said": "لما أجرى الله تعالى العادة أن لا بد للإنسان من أخيارهم وأشرارهم من بلغة في الدنيا، صار المؤمن يطلبها كما يطلبها الكافر، لكن طلب المؤمن لها على سبيل الغرض قدر ما يحسن، وفي وقت ما يحسن، ولأجل الحاجة إليها .. قال بعض الصالحين: \" اللهم وسع الدنيا علي، وزهدني فيها، ولا تضيقها علي فترغبني فيها \". فقوله تعالى: ﴿ءَاتِنَا فِي ٱلدُّنۡيَا حَسَنَةٗ﴾ أي ما لا يستقبح عاجلا وآجلا ويكون ذريعة إلى المقصد، ﴿وَفِي ٱلۡأٓخِرَةِ حَسَنَةٗ﴾ أي ثوابا ورحمة وعلى هذا قال الحسن الحسنة في الدنيا العلم والعبادة، وفي الآخرة: الجنة ﴿وَقِنَا عَذَابَ ٱلنَّارِ﴾ أي: احفظنا من الشهوات والذنوب المؤدية إلى النار", "en": "Allah made it the way of things that every person, good or bad, needs something of this world to live on; so the believer asks for it as the disbeliever does — but he asks for it as a means, in the measure that is good, at the time it is good, and because he needs it. A righteous man used to pray: \"O Allah, make the world wide for me and make me indifferent to it; do not make it narrow for me, so that I come to crave it.\"\n\"Good in this world\" is what is not ugly now or later, and serves as a road to the goal; \"good in the next\" is reward and mercy. Al-Hasan said: good in this world is knowledge and worship; good in the next is Paradise. \"And protect us from the punishment of the Fire\" — guard us from the appetites and sins that lead to it.", "ar": "لمّا أجرى الله العادة أنه لا بدّ للإنسان — خيّرًا كان أو شرّيرًا — من بُلغةٍ في الدنيا، صار المؤمن يطلبها كما يطلبها الكافر؛ لكنّ طلب المؤمن لها على سبيل الغرض، بقدر ما يحسن، وفي وقت ما يحسن، ولأجل الحاجة إليها. وقال بعض الصالحين: «اللهم وسّع الدنيا عليّ وزهّدني فيها، ولا تضيّقها عليّ فترغّبني فيها».\nفـ﴿ءَاتِنَا فِي ٱلدُّنۡيَا حَسَنَةٗ﴾: ما لا يُستقبح عاجلًا وآجلًا ويكون ذريعةً إلى المقصد؛ و﴿وَفِي ٱلۡأٓخِرَةِ حَسَنَةٗ﴾: ثوابًا ورحمة. وقال الحسن: الحسنة في الدنيا العلم والعبادة، وفي الآخرة الجنّة. و﴿وَقِنَا عَذَابَ ٱلنَّارِ﴾: احفظنا من الشهوات والذنوب المؤدّية إليها.", "links": [{"ref": "28:77", "q": "﴿وَٱبۡتَغِ فِيمَآ ءَاتَىٰكَ ٱللَّهُ ٱلدَّارَ ٱلۡأٓخِرَةَۖ وَلَا تَنسَ نَصِيبَكَ مِنَ ٱلدُّنۡيَاۖ﴾", "en": "This world as a means to the next", "ar": "الدنيا وسيلةٌ إلى الآخرة"}, {"ref": "4:134", "q": "﴿مَّن كَانَ يُرِيدُ ثَوَابَ ٱلدُّنۡيَا فَعِندَ ٱللَّهِ ثَوَابُ ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۚ﴾", "en": "Both are with Allah", "ar": "الثوابان عند الله"}], "v": 1, "p": 425, "pe": 425, "sid": 426},
  {"a": [202, 202], "h": "\"They will have a share of what they earned\" — and what \"swift in reckoning\" means", "hAr": "﴿أُوْلَٰٓئِكَ لَهُمۡ نَصِيبٞ مِّمَّا كَسَبُواْۚ وَٱللَّهُ سَرِيعُ ٱلۡحِسَابِ﴾", "said": "بين تعالى أن من جمع بين طلب دنياه وأخراه، ولم يقتصر على طلب الدنيا الموصوفة بقوله تعالى: ﴿إِنَّمَا مَثَلُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا كَمَآءٍ أَنزَلۡنَٰهُ مِنَ ٱلسَّمَآءِ﴾ الآية، فقد تناول نصيبه المأمور به في قوله: ﴿وَلَا تَنسَ نَصِيبَكَ مِنَ ٱلدُّنۡيَاۖ﴾، ولم يكن كمن قال فيهم: ﴿وَقَدِمۡنَآ إِلَىٰ مَا عَمِلُواْ مِنۡ عَمَلٖ فَجَعَلۡنَٰهُ هَبَآءٗ مَّنثُورًا﴾، ولما كان الحساب يكشف عن مجمل الشيء وتفصيله، نبه بذلك على إحاطته بأفعال عباده ووقوفه على حقائقها، وذكر \" السريع \" تنبيها أن ذلك منه، لا في زمان ولا بفكرة، وذلك أبلغ ما يمكن أن يتصور به الكافة سرعة فعل الله عز وجل", "en": "Nasib, a share, first meant something set up in place, then the portion fixed for someone.\nWhoever seeks both this world and the next — and does not settle for this world alone, which is \"like water We sent down from the sky\" and soon gone — has taken the share he was told to take (\"do not forget your share of this world\"), and is not like those whose works are made \"scattered dust\".\nReckoning lays open a thing in sum and in detail; so it tells of Allah's knowledge encircling His servants' deeds and their inner truth. \"Swift\" means His reckoning takes no time and needs no thought — the nearest picture people can form of how swiftly Allah acts.", "ar": "«النصيب» في الأصل المنصوب، ثم جُعل السهم المقرّر نصيبًا.\nبيّن تعالى أن من جمع بين طلب دنياه وآخرته، ولم يقتصر على طلب الدنيا الموصوفة بقوله ﴿إِنَّمَا مَثَلُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا كَمَآءٍ أَنزَلۡنَٰهُ مِنَ ٱلسَّمَآءِ﴾، فقد تناول نصيبه المأمور به في ﴿وَلَا تَنسَ نَصِيبَكَ مِنَ ٱلدُّنۡيَاۖ﴾، ولم يكن كمن قال فيهم ﴿وَقَدِمۡنَآ إِلَىٰ مَا عَمِلُواْ مِنۡ عَمَلٖ فَجَعَلۡنَٰهُ هَبَآءٗ مَّنثُورًا﴾.\nولمّا كان الحساب يكشف عن مجمل الشيء وتفصيله، نبّه به على إحاطته بأفعال عباده ووقوفه على حقائقها؛ وذكر «السريع» تنبيهًا أن ذلك منه لا في زمانٍ ولا بفكرة — وهو أبلغ ما يمكن أن يتصوّر به الكافّة سرعة فعل الله.", "links": [{"ref": "28:77", "q": "﴿وَٱبۡتَغِ فِيمَآ ءَاتَىٰكَ ٱللَّهُ ٱلدَّارَ ٱلۡأٓخِرَةَۖ وَلَا تَنسَ نَصِيبَكَ مِنَ ٱلدُّنۡيَاۖ﴾", "en": "Both shares", "ar": "النصيبان"}, {"ref": "10:24", "q": "﴿إِنَّمَا مَثَلُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا كَمَآءٍ أَنزَلۡنَٰهُ مِنَ ٱلسَّمَآءِ﴾", "en": "This world alone — soon gone", "ar": "الدنيا وحدها سريعة الزوال"}, {"ref": "6:62", "q": "﴿أَلَا لَهُ ٱلۡحُكۡمُ وَهُوَ أَسۡرَعُ ٱلۡحَٰسِبِينَ﴾", "en": "The swiftest of reckoners", "ar": "أسرع الحاسبين"}], "v": 1, "p": 425, "pe": 426, "sid": 426},
  {"a": [203, 203], "h": "\"Whoever hastens in two days, no sin — whoever delays, no sin — for the God-conscious\"", "hAr": "﴿فَمَن تَعَجَّلَ فِي يَوۡمَيۡنِ فَلَآ إِثۡمَ عَلَيۡهِ وَمَن تَأَخَّرَ فَلَآ إِثۡمَ عَلَيۡهِۖ لِمَنِ ٱتَّقَىٰۗ﴾", "said": "والحشر: ضم المتفرق وسوقه ... ورفع الإثم عن المتعجل والمتأخر على وجه الإباحة وقيل: معنى رفع الإثم أنه حط ذنوبهما بإقامتهما الحج تعجل أو تأخر بشرط أن يكون متقيا- تنبيها أن الاعتبار بالتقوى فقط، وعلى ذلك دل قوله- عليه السلام- \" من حج ولم يرفث ولم يفسق رجع كيوم ولدته أمه \"", "en": "\"No sin on him\" may simply permit both — leaving Mina after two days, or staying the third. Another reading: his sins are taken away by performing the Hajj, whether he hastens or delays — on one condition, that he is God-conscious. What counts is God-consciousness alone; as the Prophet ﷺ said, \"whoever performs the Hajj without obscenity or wickedness returns as on the day his mother bore him\".\n\"And know that you will be gathered to Him\" — hashr is gathering the scattered and driving them on: be mindful of Allah, certain that you return to Him and will be asked about your deeds.", "ar": "رُفع الإثم عن المتعجّل والمتأخّر على وجه الإباحة؛ وقيل: معناه حطّ ذنوبهما بإقامتهما الحجّ، تعجّل أو تأخّر، بشرط أن يكون متّقيًا — تنبيهًا على أن الاعتبار بالتقوى فقط؛ وعليه دلّ قوله ﷺ: «من حجّ فلم يرفث ولم يفسق رجع كيوم ولدته أمّه».\nو«الحشر» ضمّ المتفرّق وسوقه: ﴿وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّكُمۡ إِلَيۡهِ تُحۡشَرُونَ﴾ — متحقّقين أنكم إليه راجعون، وعلى أعمالكم محاسَبون.", "links": [{"ref": "5:27", "q": "﴿إِنَّمَا يَتَقَبَّلُ ٱللَّهُ مِنَ ٱلۡمُتَّقِينَ﴾", "en": "What counts is God-consciousness", "ar": "الاعتبار بالتقوى"}, {"ref": "2:281", "q": "﴿وَٱتَّقُواْ يَوۡمٗا تُرۡجَعُونَ فِيهِ إِلَى ٱللَّهِۖ﴾", "en": "Gathered back to Him", "ar": "الرجوع إليه"}], "v": 1, "p": 426, "pe": 426, "sid": 427},
  {"a": [204, 204], "h": "\"One whose talk about this world impresses you\" — this world and the next are like two co-wives", "hAr": "﴿وَمِنَ ٱلنَّاسِ مَن يُعۡجِبُكَ قَوۡلُهُۥ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا﴾ — الدنيا والآخرة كالضرّتين", "said": "التعجب حيرة تعرض للإنسان عن جهل سبب الشيء وليس هو شيء ما له في ذاته حالة، بل هو بحسب الإضافات إلى من يعرف السبب وإلى من لا يعرفه، ولهذا قال قوم كل شيء عجب، وقال قوم: لا شيء عجب، وحقيقة أعجبني كذا، أي ظهر لي ظهورا لم أعرف سببه ... واستعير الألد للجدل الذي لا يمكنه صرف رأسه عما عض عليه، ولما كانت الدنيا والآخرة كالمتضادين حتى قال أمير المؤمنين: [أزنها بكفتي ميزان] لا ترجح إحداهما إلا بنقصان الأخرى، وقال: مرة كالضرتين إذا أرضيت إحداهما أسخطت الأخرى، فمن حذق في إحديهما خرق في أخرى ... ويحلف بأن قلبه [مطمئن بالإيمان] ومطابق للسانه وهو يجادل في ذلك ويخاصم، وقوله تعالى ﴿وَيُشۡهِدُ ٱللَّهَ عَلَىٰ مَا فِي قَلۡبِهِۦ﴾ إشارة إلى نحو ما وصف به المنافقين، حيث قالوا: ﴿نَشۡهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِۗ﴾", "en": "Wonder is the bewilderment a person feels when he does not know the cause of something. It is not in the thing itself but in its relation to whoever knows the cause and whoever does not — which is why some said everything is wonderful, and others that nothing is. \"It impressed me\" means it appeared to me in a way whose cause I did not know.\nAladd, \"most quarrelsome\", is first one who twists his neck away — the arrogant — then the stubborn disputer who cannot turn his head from what he has clamped his teeth on.\nThis world and the next are like opposites. 'Ali said they are like the two pans of a scale — one cannot go down without the other going up — and like two co-wives: please one and you anger the other. So whoever is clever in one tends to be clumsy in the other. Hence some people, when you meet them, impress you with their handling of worldly things; they swear their heart matches their tongue, and argue and quarrel over it — \"and he calls Allah to witness what is in his heart\", like the hypocrites who said \"we bear witness that you are the Messenger of Allah\".", "ar": "«التعجّب» حيرةٌ تعرض للإنسان عن جهل سبب الشيء، وليس حالةً في ذات الشيء، بل هو بحسب الإضافة إلى من يعرف السبب ومن لا يعرفه؛ ولهذا قال قومٌ: كلّ شيءٍ عجب، وقال قوم: لا شيء عجب. و«أعجبني كذا»: ظهر لي ظهورًا لم أعرف سببه.\nو«الألدّ» المائل صفحة العنق، ثم عُبّر به عن المتكبّر، ثم استُعير للجَدِل الذي لا يمكنه صرف رأسه عمّا عضّ عليه.\nولمّا كانت الدنيا والآخرة كالمتضادّين — قال عليٌّ: هما ككفّتي الميزان، لا ترجح إحداهما إلا بنقصان الأخرى؛ وقال مرّة: كالضرّتين، إذا أرضيت إحداهما أسخطت الأخرى —، فمن حذق في إحداهما خرِق في الأخرى. فنبّه أن من الناس من إذا صادفته وجدته معجِبًا في أمور دنياه، يحلف أن قلبه مطمئنٌّ بالإيمان مطابقٌ للسانه، وهو يجادل ويخاصم؛ و﴿وَيُشۡهِدُ ٱللَّهَ عَلَىٰ مَا فِي قَلۡبِهِۦ﴾ إشارةٌ إلى نحو ما وُصف به المنافقون: ﴿قَالُواْ نَشۡهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِۗ﴾.", "links": [{"ref": "63:4", "q": "﴿وَإِذَا رَأَيۡتَهُمۡ تُعۡجِبُكَ أَجۡسَامُهُمۡۖ وَإِن يَقُولُواْ تَسۡمَعۡ لِقَوۡلِهِمۡۖ﴾", "en": "Impressive to look at and listen to", "ar": "معجِبون منظرًا ومقالًا"}, {"ref": "63:1", "q": "﴿إِذَا جَآءَكَ ٱلۡمُنَٰفِقُونَ قَالُواْ نَشۡهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِۗ﴾", "en": "Calling Allah to witness", "ar": "إشهاد الله"}, {"ref": "87:16-17", "q": "﴿بَلۡ تُؤۡثِرُونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا ۝ وَٱلۡأٓخِرَةُ خَيۡرٞ وَأَبۡقَىٰٓ﴾", "en": "Preferring this world", "ar": "إيثار الدنيا"}], "v": 1, "p": 427, "pe": 428, "sid": 428}
];
